// Eldoria helper — dán toàn bộ vào javascript_tool (trang ngoài). Sống qua các lần đổi map
// (trang ngoài dùng history, chỉ iframe frames[0] tải lại).
// G(...cmds)  chạy tuần tự (tổng chờ ≤ 40 s vì javascript_tool timeout 45 s):
//   'look' | 'q' | 'mobs' | 'zones' | 'wait <until,..> <giây>' | 'sleep <giây>' | lệnh act (go/attack/skill/use/talk/pick/auto/open/click/close/mount)
// BG(...cmds) chạy nền, RJ(giây) lấy log; WQ(giây) chờ bước nhiệm vụ đổi; ST() trạng thái 1 dòng;
// BAG() túi; NPCS() NPC cả map; QS() nhiệm vụ; PUMP() bơm khung hình khi cửa sổ ẩn (rAF ngừng).
// Nhịp Worker (28/10): trang ẩn → trình duyệt bóp setTimeout/setInterval (≥ 1 s; chuỗi dài 1 lần/phút) → mini game hỏng (câu hụt ½, 4′/lượt; đàn trượt).
// Hẹn giờ trong Worker không bị bóp → setTimeout/setInterval của trang ngoài chạy theo nhịp Worker 10 ms (mọi công cụ + AP hưởng); PUMP bơm khung hình theo cùng nhịp.
if (!window.__wt) (() => {
  const nST = setTimeout.bind(window), nCT = clearTimeout.bind(window), nSI = setInterval.bind(window), nCI = clearInterval.bind(window);
  const T = new Map(); let id = 1e7;
  const wk = new Worker(URL.createObjectURL(new Blob(['setInterval(()=>postMessage(0),10)'], { type: 'text/javascript' })));
  wk.onmessage = () => {
    const n = performance.now(), due = [];
    for (const [k, t] of T) if (n >= t.at) { due.push(t); if (t.iv) t.at = n + t.iv; else T.delete(k); }
    for (const t of due) try { t.f(...t.a); } catch (e) { console.error(e); }
    if (window.__pumpTick) window.__pumpTick();
  };
  window.setTimeout = (f, ms, ...a) => typeof f !== 'function' ? nST(f, ms, ...a) : (T.set(++id, { f, a, at: performance.now() + (+ms || 0) }), id);
  window.setInterval = (f, ms, ...a) => typeof f !== 'function' ? nSI(f, ms, ...a) : (T.set(++id, { f, a, at: performance.now() + Math.max(4, +ms || 0), iv: Math.max(4, +ms || 0) }), id);
  window.clearTimeout = window.clearInterval = k => { if (T.has(k)) T.delete(k); else { nCT(k); nCI(k); } };
  window.__wt = { T, wk };
})();
window.PUMP = () => {
  const W = frames[0];
  if (!W || W.__pumpF) return;
  let ok = false; try { ok = W.eval('typeof engine!=="undefined"&&!!engine._activeRenderLoops'); } catch (e) {}
  if (!ok) return; // engine là biến let trong iframe, không nằm trên window
  if (W.__pump) W.clearInterval(W.__pump); // bản cũ bơm bằng setInterval của iframe (bị bóp khi ẩn)
  W.eval(`(()=>{window.__rafLast=performance.now();const hb=()=>{window.__rafLast=performance.now();requestAnimationFrame(hb)};requestAnimationFrame(hb);window.__pumpN=0;window.__pump=1;
  window.__pumpF=()=>{if(performance.now()-window.__rafLast<150)return;try{engine.beginFrame();for(const f of engine._activeRenderLoops)f();engine.endFrame();window.__pumpN++}catch(e){window.__pumpErr=String(e)}}})()`);
};
window.__pumpTick = () => { const n = performance.now(); if (n - (window.__pl || 0) < 40) return; window.__pl = n; try { const W = frames[0]; if (W && W.__pumpF) W.__pumpF(); } catch (e) {} };
window.QS = () => {
  const W = frames[0], Q = W && W.QUEST_B; if (!Q) return 'no quest api';
  const c = Q.cur(); if (!c || !c.b) return 'no quest';
  const st = Q.state(), s = c.st || {};
  return `Q ${c.b.id} "${c.b.title}" L${c.b.level} step ${c.i + 1}/${c.b.steps.length} [${s.type}] ${s.text || ''} · count ${st.count}/${s.n || c.need || ''}` + (c.wait ? ' wait' + c.wait : '') + (s.hint ? '\n hint: ' + s.hint : '');
};
window.ST = () => { try { return frames[0].eval(`'L'+(PLAYER.level||'?')+' HP'+Math.round(100*hero.hp/hero.maxHp)+'% '+(AUTO.on?'AUTO':'manual')+' bag '+bag.slice(0,PLAYER.bagSize).filter(Boolean).length+'/'+PLAYER.bagSize+' gold '+(PLAYER.gold??'?')+' map '+MAP_ID+' @'+Math.round(hero.x/10)+','+Math.round(hero.y/10)`); } catch (e) { return 'ST err ' + e; } };
window.MOBS = () => frames[0].eval(`(()=>{const c={};for(const m of mobs){if(m.dead)continue;const k=(m.sp.name||m.sp.id);c[k]=c[k]||{n:0,x:0,y:0,lv:m.level};c[k].n++;c[k].x+=m.x;c[k].y+=m.y;}return 'me '+Math.round(hero.x/10)+','+Math.round(hero.y/10)+' | '+Object.entries(c).map(([k,v])=>k+' x'+v.n+' L'+v.lv+' @'+Math.round(v.x/v.n/10)+','+Math.round(v.y/v.n/10)).join(' · ')})()`);
window.ZONES = () => frames[0].eval(`(MAP.zones||[]).map((z,i)=>'z'+i+' L'+z.level.join('-')+' ['+z.species.map(s=>(SP.species[s]&&SP.species[s].name)||s).join(',')+'] camps '+z.camps.map(c=>Math.round(c.x/10)+','+Math.round(c.y/10)).join(' ')).join('\\n')+(MAP.bosses&&MAP.bosses.length?'\\nbosses '+MAP.bosses.map(b=>b.id+'@'+Math.round(b.x/10)+','+Math.round(b.y/10)).join(' '):'')`);
window.BAG = () => frames[0].eval(`bag.slice(0,PLAYER.bagSize).map((b,i)=>b?i+':'+b.name+(b.n>1?'x'+b.n:'')+'('+b.type+(b.slot?'/'+b.slot:'')+')':null).filter(Boolean).join(' · ')`);
window.NPCS = () => frames[0].eval(`npcs.map(n=>(n.id||'')+':'+n.name+'@'+Math.round(n.x/10)+','+Math.round(n.y/10)).join(' · ')`);
// lệnh `go` của API agent đi bằng routeTo nhưng KHÔNG gọi mountAuto (chỉ chỉ-đường của người chơi mới gọi), và qua cổng thì iframe tải lại
// → canh liên tục mỗi 2 s: đang có đích, chưa cưỡi, không Auto đánh → mountAuto() (tự bỏ qua khi đang mở bảng / bận)
window.RIDE = () => { if (window.__rideT) return; window.__rideT = setInterval(() => { try { frames[0].eval('typeof mountAuto==="function"&&hero&&hero.dest&&!hero.mounted&&!(AUTO&&AUTO.on)&&mountAuto()'); } catch (e) {} }, 2000); };
RIDE();
window.G = async (...cmds) => {
  const out = [];
  for (const c of cmds) {
    const W = frames[0], A = W && W.ZY_AGENT;
    if (!A) { out.push('[no agent yet]'); break; }
    try { PUMP(); } catch (e) {}
    let r;
    try {
      if (c === 'look') r = await A.run('look');
      else if (c === 'q') r = QS();
      else if (c === 'mobs') r = MOBS();
      else if (c === 'zones') r = ZONES();
      else if (c.startsWith('wait ')) { const [, u, s] = c.split(' '); r = await A.run('wait', { until: u.split(','), max_s: +(s || 30) }); }
      else if (c.startsWith('sleep ')) { await new Promise(z => setTimeout(z, +c.slice(6) * 1000)); r = 'ok'; }
      else { r = await A.run('act', { cmd: c }); if (/^go /.test(c)) RIDE(); }
    } catch (e) { r = 'EXC ' + e; }
    out.push('>' + c + '\n' + r);
  }
  return out.join('\n');
};
window.BG = (...cmds) => { const job = { log: [], done: false }; window.__job = job; (async () => { for (const c of cmds) { if (job.stop) break; job.log.push(await G(c)); } job.done = true; })(); return 'started'; };
window.RJ = async (sec = 35) => { const j = window.__job; if (!j) return 'no job'; const t = Date.now(); while (!j.done && Date.now() - t < sec * 1000) await new Promise(r => setTimeout(r, 500)); return (j.done ? '[DONE]\n' : '[RUNNING]\n') + j.log.splice(0).join('\n'); };
window.WQ = async (sec = 38) => { const k = () => { try { PUMP(); const c = frames[0].QUEST_B.cur(); return c && c.b ? c.b.id + ':' + c.i : ''; } catch (e) { return 'loading'; } }; const s = k(), t = Date.now(); while (Date.now() - t < sec * 1000 && k() === s) await new Promise(r => setTimeout(r, 1000)); return (k() !== s ? 'STEP CHANGED ' : '') + QS() + '\n' + ST(); };
// Watchdog: tự cài PUMP mỗi giây (iframe tải lại giữa chừng khi tự đi qua nhiều map).
if (window.__wd) clearInterval(window.__wd);
window.__wd = setInterval(() => { try { PUMP(); } catch (e) {} }, 1000);
// Tiện ích thêm
window.CH = async () => { const r = await G('open champ'); await G('close'); return (r.match(/(In battle · \w+|\w+ · [^·]+ · \w+ · \w+ · (Tank|Support|Damage) · level \d+ \/ \d+ · \d+)/g) || []).map(s => s.replace(/ · [^·]+ · \w+ · \w+ · /, ' ')).join(' | '); };
window.SWAP = (name) => { const b = [...frames[0].document.querySelectorAll('button.cpip')].find(e => e.getAttribute('aria-label').startsWith(name)); if (!b) return 'no slot ' + name; b.click(); return b.getAttribute('aria-label'); }; // tướng gục chỉ hồi khi vào thành
window.ID = async (re) => { const l = await G('look'); const m = l.match(new RegExp('([a-z]\\d+) ' + re)); return m ? m[1] : null; };
window.TALK = async (name) => { const id = await ID(name); return id ? G('talk ' + id) : 'no npc ' + name; };
window.STEPS = () => { const c = frames[0].QUEST_B.cur(); return c.b.steps.map((s, i) => (i + 1) + '.' + s.type + (s.map ? '@' + s.map : '') + (s.n ? ' x' + s.n : '') + ' ' + s.text).join('\n'); };
// Toàn cảnh tiến độ: nhiệm vụ chính + phụ theo map + việc ngày + trạng thái.
window.QQ = () => { const W = frames[0]; const st = W.QUEST_B.state(); const side = Object.entries(st.sideP || {}).map(([m, p]) => `side ${m}:${st.side[m]} ${p.name} ${p.kills}/${p.n} item/${p.k} step${p.step}`).join(' | '); let d = ''; try { const ds = W.dailyState(); d = 'daily ' + ds.tasks.map(t => `${t.kind} ${t.got}/${t.n}${t.st === 'on' ? '' : '(' + t.st + ')'}`).join(', '); } catch (e) {} return QS() + '\n' + side + '\n' + d + '\n' + ST(); };
// GEAR(): đồ đang mặc của từng tướng. Chấm điểm/phân đồ: tools/gear.js (GEARPLAN/GEARDO).
window.GEAR = () => frames[0].eval(`Object.keys(EQUIP).map(c=>c+'(L'+lvlOf(c)+'): '+Object.entries(EQUIP[c]).filter(([k,v])=>v).map(([k,v])=>k+'='+v.name+' q'+v.q+' L'+v.lvl).join('; ')).join('\\n')`);
// Nhiệm vụ phụ theo map (NPC Thợ Săn/Trinh Sát/Liều Mạng, 1 nhiệm vụ/map, tối đa 5 cùng lúc).
// SIDE_ST(): trạng thái map hiện tại.  SIDE_GO(): nhận (nếu chưa) + tới bãi + auto on.  SIDE_TURN(): trả.
window.SIDE_ST = () => { const W = frames[0], m = W.eval('MAP_ID'), st = W.QUEST_B.state(); const p = st.sideP[m]; return m + ': ' + (st.side[m] || 'none') + (p ? ` ${p.name} kills ${p.kills}/${p.n} step${p.step}` : ''); };
// look chỉ liệt kê NPC trong tầm nhìn → đi tới nơi (3×30 s) rồi talkTo thẳng theo id; trả nội dung look có nút "side quest" (null = map không có NPC phụ)
window.SIDE_NPC = async () => {
  const W = frames[0], xy = W.eval(`(()=>{const n=npcs.find(n=>/hunter|scout|daredevil/.test(n.id)||/Nhiệm vụ phụ/.test(n.role||''));return n?n.id+' '+Math.round(n.x/10)+','+Math.round(n.y/10+2):''})()`);
  if (!xy) return null; const [id, p] = xy.split(' ');
  await G('auto off'); for (let i = 0; i < 3; i++) { const r = await G('go ' + p, 'wait arrived 30'); if (/Arrived|already/i.test(r)) break; }
  W.eval(`talkTo(npcs.find(n=>n.id==='${id}'))`); let l = '';
  for (let i = 0; i < 8; i++) { await new Promise(z => setTimeout(z, 1000)); l = await G('look'); if (/side quest/.test(l)) break; }
  return l;
};
window.SIDE_GO = async () => {
  const W = frames[0], m = W.eval('MAP_ID'); let st = W.QUEST_B.state();
  if (!st.side[m]) {
    const l = await SIDE_NPC(); if (l === null) return 'map không có NPC phụ';
    const acc = (l.match(/\[(e\d+)\] Accept side quest/) || [])[1]; if (!acc) return 'không thấy nút nhận: ' + l.slice(l.indexOf('Open panels'), l.indexOf('Open panels') + 200);
    await G('click ' + acc, 'close'); st = W.QUEST_B.state();
  }
  const c = st.sideP[m].camp; await G('go ' + Math.round(c[0] / 10) + ',' + Math.round(c[1] / 10), 'wait arrived 30', 'auto on'); return SIDE_ST();
};
window.SIDE_TURN = async () => { const l = await SIDE_NPC(); if (l === null) return 'không có NPC phụ'; const t = (l.match(/\[(e\d+)\] Turn in side quest[^\n]*/) || []); if (!t[1]) return 'không thấy nút trả'; await G('click ' + t[1], 'close'); return t[0]; };
// Tên map hiển thị từ id (lệnh `go` nhận tên).
window.MAPNAME = (id) => { try { return frames[0].eval(`MANIFEST.maps['${id}'].name`); } catch (e) { return id; } };
// Job nền tổng quát (chạy lâu hơn timeout 45 s): JOB(async log=>{...}); xem bằng RJ(1); dừng: __job.stop=true.
window.JOB = (fn) => { const job = { log: [], done: false }; window.__job = job; (async () => { try { await fn(m => job.log.push(m)); } catch (e) { job.log.push('EXC ' + e); } job.done = true; })(); return 'started'; };
// Nhiệm vụ phụ trọn gói ở map hiện tại.
window.SIDE_FULL = () => JOB(async log => { let W = frames[0]; const m = W.eval('MAP_ID'); log(await SIDE_GO()); const t = Date.now(); while (Date.now() - t < 15 * 60e3) { if (window.__job.stop) return; W = frames[0]; if (W.eval('MAP_ID') !== m) { log('left map ' + W.eval('MAP_ID')); return; } const p = W.QUEST_B.state().sideP[m]; if (p && p.step >= 2) break; const hp = W.eval('hero.hp/hero.maxHp'); if (hp < 0.35) { await G('skill 5'); log('emergency potion hp ' + Math.round(hp * 100)); } await new Promise(r => setTimeout(r, 2000)); } log(SIDE_ST()); log(await SIDE_TURN()); });
// Bước nhiệm vụ chính loại kill: tới map, bãi đúng loài, auto on, chờ bước đổi.
window.KILLQ = () => JOB(async log => { let W = frames[0]; const c0 = W.QUEST_B.cur(); const key = c0.b.id + ':' + c0.i; const st = c0.st; if (st.type !== 'kill') { log('not kill step'); return; }
  const mp = () => { try { return frames[0].eval('MAP_ID'); } catch (e) { return ''; } };
  if (mp() !== st.map) { await G('go ' + MAPNAME(st.map)); const t = Date.now(); while (mp() !== st.map && Date.now() - t < 180e3) await new Promise(r => setTimeout(r, 2000)); await new Promise(r => setTimeout(r, 5000)); await G('close'); }
  W = frames[0]; const camps = JSON.parse(W.eval(`JSON.stringify((MAP.zones||[]).flatMap(z=>z.camps.map((c,i)=>({x:Math.round(c.x/10),y:Math.round(c.y/10),sp:campSpecies(z,c,i)}))))`)).filter(c => c.sp === st.sp);
  if (!camps.length) { log('no camp for ' + st.sp); return; } const camp = camps[0]; log('camp ' + camp.x + ',' + camp.y);
  await G('go ' + camp.x + ',' + camp.y, 'wait arrived 25', 'auto on');
  const t = Date.now(); while (Date.now() - t < 20 * 60e3) { if (window.__job.stop) return; W = frames[0]; let k = ''; try { const c = W.QUEST_B.cur(); k = c.b.id + ':' + c.i; } catch (e) {} if (k && k !== key) break; try { const hp = W.eval('hero.hp/hero.maxHp'); if (hp < 0.35) { await G('skill 5'); log('pot ' + Math.round(hp * 100)); } if (!W.eval('AUTO.on')) { await G('go ' + camp.x + ',' + camp.y, 'wait arrived 20', 'auto on'); log('re-auto'); } } catch (e) {} await new Promise(r => setTimeout(r, 2500)); }
  log('done: ' + QS()); });
// Phó bản: đi theo MAP.route (trại cN, boss bN), dọn từng điểm bằng Auto. Gọi khi đã ở trong phó bản.
window.DGRUN = () => JOB(async log => { const ev = s => { try { return frames[0].eval(s); } catch (e) { return undefined; } };
  const pts = JSON.parse(ev(`JSON.stringify((()=>{const cs=(MAP.zones||[]).flatMap(z=>z.camps);const bs=MAP.bosses||[];return (MAP.route||[]).map(id=>{if(id[0]==='c'){const c=cs[+id.slice(1)];return {id,x:Math.round(c.x/10),y:Math.round(c.y/10)}}const b=bs.find(b=>b.id===id);return {id,x:Math.round(b.x/10),y:Math.round(b.y/10),boss:b.name}})})())`) || '[]'); log('route ' + pts.map(p => p.id).join('>'));
  for (const p of pts) { if (window.__job.stop) return; await G('auto off', 'go ' + p.x + ',' + (p.y + 3)); await G('wait arrived 20', 'auto on'); const t = Date.now(); let clear = 0;
    while (Date.now() - t < 240e3) { if (window.__job.stop) return; const hp = ev('hero.hp/hero.maxHp'); if (hp < 0.4) await G('skill 5'); const near = ev(`mobs.filter(m=>!m.dead&&m.hp>0&&Math.hypot(m.x/10-${p.x},m.y/10-${p.y})<32).length`); if (!near) { if (++clear >= 3) break; } else clear = 0; if (!ev('AUTO.on')) await G('auto on'); if (ev('MAP.kind') !== 'dungeon') { log('rời phó bản ở ' + p.id); return; } await new Promise(r => setTimeout(r, 2000)); }
    log(p.id + (p.boss ? ' (' + p.boss + ')' : '') + ' xong ' + Math.round((Date.now() - t) / 1000) + 's hp' + Math.round(100 * ev('hero.hp/hero.maxHp'))); }
  log('route done · ' + QS().split('\n')[0]); });
// Lưu mọi hàm đang sống vào localStorage 'zy_tools' (nạp lại: eval(localStorage.getItem('zy_tools'))).
window.SAVE_TOOLS = () => { const names = ['PUMP', 'QS', 'ST', 'MOBS', 'ZONES', 'BAG', 'NPCS', 'G', 'BG', 'RJ', 'WQ', 'CH', 'SWAP', 'ID', 'TALK', 'STEPS', 'QQ', 'GEAR', 'MAPNAME', 'KILLQ', 'JOB', 'SIDE_ST', 'SIDE_GO', 'SIDE_TURN', 'SIDE_FULL', 'GEAR_SCORE', 'GEARPLAN', 'GEARDO', 'SAVE_TOOLS', 'DGRUN']; let src = names.filter(n => typeof window[n] === 'function').map(n => 'window.' + n + '=' + window[n].toString() + ';').join('\n'); src += '\nwindow.GEAR_STD=' + JSON.stringify(GEAR_STD) + ';window.GEAR_W=' + JSON.stringify(GEAR_W) + ';\nif(window.__wd)clearInterval(window.__wd);window.__wd=setInterval(()=>{try{PUMP()}catch(e){}},1000);'; localStorage.setItem('zy_tools', src); return src.length; };
// SYNC(v, sha): đồng bộ toàn bộ file tools/*.js → localStorage (zy_tools = helper+gear+jobs · zy_ap · zy_ap2) từ bundle.json đã đăng (publish_ext.ps1)
// rồi nạp lại giữ AP.k2 + log (AP dừng — gọi AP.start() sau). sha = commit edge-extension (raw GitHub nhánh main bị CDN giữ bản cũ ~5′); v = bản mong đợi.
window.SYNC = async (want, sha) => {
  const b = await (await fetch('https://raw.githubusercontent.com/ngotrongduong/Eldoria-autopilot/' + (sha || 'main') + '/bundle.json?t=' + Date.now(), { cache: 'no-store' })).json();
  if (want && b.v !== want) return 'bundle cũ ' + b.v;
  const f = {}; b.files.forEach(x => f[x.n] = x.src);
  const tools = f['helper.js'] + '\n;\n' + f['gear.js'] + '\n;\n' + f['jobs.js'];
  for (const s of [tools, f['autopilot.js'], f['autopilot_ext.js']]) new Function(s);
  localStorage.setItem('zy_tools', tools); localStorage.setItem('zy_ap', f['autopilot.js']); localStorage.setItem('zy_ap2', f['autopilot_ext.js']);
  const k2 = window.AP && AP.k2, log = (window.AP && AP.log) || [];
  if (window.AP) AP.stop();
  eval(localStorage.getItem('zy_tools')); eval(localStorage.getItem('zy_ap')); eval(localStorage.getItem('zy_ap2'));
  if (k2) AP.k2 = k2; AP.log = log.concat(AP.log);
  return 'nạp ' + b.v;
};
'helper ok';

// GEARPLAN: chấm điểm đồ theo vai trò và phân món trong túi cho tướng được lợi nhất.
// Điểm 1 dòng = giá trị / mức chuẩn 1 dòng ở cấp 1 (KB 03 §8.1) × trọng số vai trò.
// GEARPLAN()  -> kế hoạch (chữ);  GEARDO() -> thực hiện (đổi tướng + equip theo chỉ số túi).
window.GEAR_STD = { 'Máu': 20, 'Công': 1.3, 'Giáp': 4, 'Kháng phép': 6, 'Hồi máu / giây': 0.7, 'Né tránh': 1.3, 'Hút máu': 2, 'Hút máu quái': 2,
  'Giảm sát thương': 1.3, 'Kháng khống chế': 10, 'Hiệu quả hồi': 10, 'Phản sát thương': 4, 'Bạo kích': 3.4, 'Sát thương bạo kích': 20, 'Chính xác': 4,
  'Xuyên giáp': 3.4, 'Sát thương đòn thường': 5, 'Sát thương kỹ năng': 3.4, 'Tốc đánh': 0.1, 'Giảm hồi chiêu': 2, 'Tốc tích Nộ': 6.6, 'Tốc chạy': 4 };
window.GEAR_W = {
  Tank:    { 'Máu': 1.3, 'Giáp': 1.3, 'Kháng phép': 1.3, 'Giảm sát thương': 1.3, 'Kháng khống chế': 1.0, 'Hồi máu / giây': 1.0, 'Phản sát thương': 0.9, 'Công': 0.6, _: 0.6 },
  Damage:  { 'Công': 1.4, 'Bạo kích': 1.3, 'Sát thương bạo kích': 1.2, 'Xuyên giáp': 1.2, 'Sát thương đòn thường': 1.2, 'Sát thương kỹ năng': 1.0, 'Tốc đánh': 1.2, 'Chính xác': 0.9, 'Máu': 0.8, 'Giáp': 0.6, 'Kháng phép': 0.6, _: 0.6 },
  Support: { 'Máu': 1.0, 'Giáp': 0.9, 'Kháng phép': 0.9, 'Hiệu quả hồi': 1.2, 'Giảm hồi chiêu': 1.2, 'Tốc tích Nộ': 1.1, 'Công': 0.9, 'Hồi máu / giây': 1.0, _: 0.7 },
};
window.GEAR_SCORE = (item, role) => {
  if (!item) return 0;
  const W = GEAR_W[role] || GEAR_W.Damage;
  const parts = [...String(item.base || '').split('·'), ...(item.lines || [])];
  let s = 0;
  for (const p of parts) {
    const m = /([+-]?[\d.,]+)\s*%?\s*([^\d+]+?)\s*$/.exec(p.trim()) || /([^\d+]+?)\s*\+\s*([\d.,]+)/.exec(p.trim());
    if (!m) continue;
    let name, val;
    if (/^[+-]?[\d]/.test(m[1])) { val = parseFloat(m[1].replace(',', '.')); name = m[2].trim(); } else { name = m[1].trim(); val = parseFloat(m[2].replace(',', '.')); }
    const std = GEAR_STD[name]; if (!std) continue;
    s += (val / std) * (W[name] ?? W._);
  }
  return Math.round(s * 100) / 100;
};
window.GEARPLAN = () => {
  const W = frames[0];
  const info = W.eval(`JSON.stringify({ champs: Object.keys(EQUIP).filter(c=>carry.includes(c)).map(c=>({id:c, role: CHS[c].role||CHS[c].pos||'', lvl: lvlOf(c), eq: EQUIP[c]})), bag: bag.slice(0,PLAYER.bagSize).map((b,i)=>b&&b.type==='equip'?{i, ...b, req: itemReq(b)}:null).filter(Boolean) })`);
  const { champs, bag } = JSON.parse(info);
  const roleOf = c => /tank|đỡ|chống/i.test(c.role) ? 'Tank' : /support|hỗ|trợ/i.test(c.role) ? 'Support' : /tank|support|damage/i.test(c.role) ? c.role : ({ brokk: 'Tank', tambo: 'Support' }[c.id] || 'Damage');
  const plan = []; const used = new Set();
  for (let guard = 0; guard < 40; guard++) {
    let best = null;
    for (const it of bag) {
      if (used.has(it.i)) continue;
      for (const c of champs) {
        if (c.lvl < (it.req || it.lvl || 1)) continue;
        const slots = String(it.slot).startsWith('ring') ? ['ring1', 'ring2'] : [it.slot];
        for (const sl of slots) {
          const role = roleOf(c), cur = c.eq[sl];
          const gain = GEAR_SCORE(it, role) - GEAR_SCORE(cur, role);
          if (gain > 0.05 && (!best || gain > best.gain)) best = { it, c, sl, gain, role };
        }
      }
    }
    if (!best) break;
    used.add(best.it.i);
    const old = best.c.eq[best.sl];
    best.c.eq[best.sl] = best.it;
    if (old) bag.push({ ...old, i: 'old:' + old.id, req: old.lvl });
    plan.push(best);
  }
  window.__gearPlan = plan.filter(p => typeof p.it.i === 'number');
  return plan.map(p => `${p.c.id}(${p.role}) ${p.sl} ← ${p.it.name} [${p.it.i}] +${p.gain.toFixed(2)}`).join('\n') || 'không có nâng cấp';
};
// Thực hiện: chỉ món đang nằm trong túi (món cũ tháo ra sẽ được xét ở lần GEARPLAN sau).
window.GEARDO = async () => {
  const W = frames[0], plan = window.__gearPlan || []; const out = [];
  const byChamp = {}; for (const p of plan) (byChamp[p.c.id] = byChamp[p.c.id] || []).push(p);
  const startActive = W.eval('active');
  for (const [cid, ps] of Object.entries(byChamp)) {
    if (W.eval('active') !== cid) { const name = W.eval(`CHS['${cid}'].name`); out.push('swap ' + SWAP(name)); await new Promise(r => setTimeout(r, 1500)); }
    if (W.eval('active') !== cid) { out.push('không đổi được sang ' + cid + ' (gục?)'); continue; }
    for (const p of ps) {
      const idx = W.eval(`bag.findIndex(b=>b&&b.id===${p.it.id})`);
      if (idx < 0) { out.push('mất món ' + p.it.name); continue; }
      W.eval(`equip(${idx}${String(p.sl).startsWith('ring') ? `,'${p.sl}'` : ''})`);
      await new Promise(r => setTimeout(r, 900));
