// ---- Nghề (world_job.js): câu cá như người chơi — Space quăng / giật / giữ để vùng xanh ôm cá. JOB.state() = {st, spot, mg {p, by, bh, fy, v}, fire} ----
// FISH(n, spotId?) chạy nền (window.__fish): tới điểm câu (spotGo) → n lượt → __fish.log. Sức Nghề hết thì vẫn câu được nhưng chỉ ra rác (EXP ×0,25) → dừng.
window.FISH = (n = 10, spotId) => {
  const W = () => frames[0], J = () => (W().JOB ? W().JOB.state() : { st: 'gone' }), F = window.__fish = { n, got: 0, ok: 0, log: [], stop: 0, done: false }; // iframe tải lại → frames[0] mới
  const key = (t) => W().dispatchEvent(new (W().KeyboardEvent)(t, { code: 'Space', key: ' ', bubbles: true }));
  const L = m => { F.log.push(new Date().toTimeString().slice(0, 8) + ' ' + m); if (F.log.length > 40) F.log.shift(); };
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  (async () => {
    try {
      if (spotId) { W().JOB.spotGo(spotId); for (let i = 0; i < 40 && J().st !== 'at'; i++) await sleep(500); }
      if (J().st !== 'at' && J().st !== 'res') { L('không đứng ở điểm câu: st=' + J().st); F.done = true; return; }
      while (!F.stop && F.got < F.n) {
        const sta = W().eval('(ECO.eco()||{}).job ? JSON.stringify(ECO.eco().job.sta.v) : "?"');
        key('keydown'); key('keyup'); // quăng
        let t0 = Date.now();
        while (J().st !== 'bite' && Date.now() - t0 < 20000) { if (J().st === 'at') break; await sleep(50); }
        if (J().st !== 'bite') { L('không cắn câu: st=' + J().st); await sleep(1500); if (J().st === 'at') continue; break; }
        await sleep(120 + Math.random() * 200); key('keydown'); key('keyup'); // giật cần
        await sleep(100);
        let held = false; t0 = Date.now();
        while (J().st === 'reel' && Date.now() - t0 < 30000) {
          const m = J().mg; if (!m) { await sleep(20); continue; }
          const fish = m.fy + 11, mid = m.by + m.bh / 2 + m.v * 0.12; // đoán trước theo vận tốc vùng xanh
          const want = fish > mid;
          if (want !== held) { key(want ? 'keydown' : 'keyup'); held = want; }
          await sleep(25);
        }
        if (held) key('keyup');
        t0 = Date.now(); while (J().st === 'send' && Date.now() - t0 < 8000) await sleep(100);
