  const V = window.__cv = { log: [], stop: 0, done: false };
  const L = m => { V.log.push(new Date().toTimeString().slice(0, 5) + ' ' + m); if (V.log.length > 40) V.log.shift(); };
  const sleep = ms => new Promise(r => setTimeout(r, ms));
