        const c = cv(); if (!c || !/^(taken|run)$/.test(c.st)) { L('hợp đồng: ' + (c ? c.st : 'không có')); break; }
        if (c.st !== lastSt) { lastSt = c.st; L('trạng thái ' + c.st); }
        const chain = c.chain && c.chain.length ? c.chain : [c.map], here = ev('MAP_ID');
        const cart = JSON.parse(ev(`JSON.stringify((()=>{const m=mobs.find(m=>!m.dead&&(m.cv||/^caravan/.test(m.spId||'')));return m?{x:m.x,y:m.y,hp:Math.round(m.hp/m.maxHp*100)}:null})())`) || 'null');
