        if (k !== lastStop) { lastStop = k; L('điểm ghé ' + k + '/' + (sm ? sm[2] : '?') + ' · xe ' + cart.hp + '% · ' + (hs.match(/Cargo · [\d/]+/) || [''])[0]); }
        const stops = c.stops && c.stops.length ? c.stops : [c.dst], tgt = stops[Math.min(k, stops.length - 1)];
        const hx = ev('hero.x'), hy = ev('hero.y'), d = Math.hypot(cart.x - hx, cart.y - hy);
        const fight = +ev(`mobs.filter(m=>!m.dead&&!m.cv&&m.state==='fight'&&Math.hypot(m.x-${cart.x},m.y-${cart.y})<150).length`) || 0;
        if (fight > 0 && (!fightT || Date.now() - fightT < 60e3)) { if (!fightT) fightT = Date.now(); if (d > 200) await G('auto off', 'go ' + Math.round(cart.x / 10) + ',' + Math.round(cart.y / 10)); else if (!ev('AUTO.on')) await G('auto on'); continue; }
        if (!fight || Date.now() - fightT > 90e3) fightT = 0;
        if (ev('AUTO.on')) await G('auto off');
