        const dx = tgt.x - cart.x, dy = tgt.y - cart.y, dl = Math.hypot(dx, dy) || 1, step = Math.min(220, dl);
        await G('go ' + Math.round((cart.x + dx / dl * step) / 10) + ',' + Math.round((cart.y + dy / dl * step) / 10));
