window.JOBDAY = (opt = {}) => {
  const w = () => frames[0], ev = s => { try { return w().eval(s); } catch (e) { return undefined; } };
  const D = window.__jd = { log: [], done: false }, L = m => { D.log.push(new Date().toTimeString().slice(0, 5) + ' ' + m); if (D.log.length > 40) D.log.shift(); };
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const P = async () => (String(await G('look')).split('Open panels:')[1] || '');
  const sta = () => { const s = JSON.parse(ev('JSON.stringify(ECO.eco().job.sta)') || 'null'); if (!s) return 0; return s.d === ev('ECO.day()') ? s.v : Math.min(300, s.v + 100); }; // +100 của ngày mới chỉ ghi khi dùng nghề lần đầu
  const closeAll = async () => { for (let i = 0; i < 4; i++) { const r = await G('close'); if (/No panel/.test(r)) break; } };
  async function chef(tab) { ev(`talkTo(npcs.find(n=>n.id==='chef'))`); await sleep(3000); const p = await P(); const b = p.match(new RegExp('\\[(e\\d+)\\] ' + tab)); if (b) { await G('click ' + b[1]); await sleep(2000); } return await P(); }
  (async () => {
    try {
      // ngân sách Sức (giá đã giảm 20% nhờ Hứng Khởi): chừa `keep` + phần hái thuốc + 1 lần khảo cổ → phần còn lại cho câu (1,6 Sức/lượt)
      const herbN = ev('ECO.eco().job.herb') ? (opt.herb || 15) : 0, digN = ev('ECO.eco().job.dig') ? (opt.dig ?? 1) : 0;
