      const n = localStorage.getItem('zy_nofish') === '1' ? 0 : Math.min(opt.max || 40, Math.floor((sta() - (opt.keep ?? 20) - (1.5 * herbN + 7 * digN) * 0.8) / 1.6)); // hái 1,5 Sức/bụi (tin #29, 27/10)
