      for (let i = 0; i < 180 && ev('MAP_ID') !== dest; i++) { if (!ev('!!hero.goal')) { if (window.AP && AP.portalOk) await AP.portalOk(); await Promise.race([G('auto off', 'go ' + MAPNAME(dest)), sleep(15000)]); } await sleep(4000); }
      if (ev('MAP_ID') !== dest) { L('không tới được ' + dest); throw 0; }
      // câu theo mẻ 10 lượt; trước mỗi mẻ giữ Hứng Khởi (đàn lại khi còn < 2′ mà việc còn lại đáng ≥ 12 Sức gốc)
      if (n >= 5) {
        L('câu ' + n + ' lượt (Sức ' + Math.round(sta()) + ')'); let got = 0;
        for (let k = 0; got < n && k < 8; k++) {
          L('Hứng Khởi: ' + await INSP.need(2 * (n - got) + 1.5 * herbN + 7 * digN, 120));
          FISH(Math.min(10, n - got), opt.spot || 's1b'); for (let i = 0; i < 200 && !(window.__fish && __fish.done); i++) await sleep(3000);
          if (!__fish.got) break; got += __fish.got;
        }
        L('câu xong: ' + got + ' lượt'); await sleep(2500); await closeAll();
      }
      // nấu: số món nấu được = Σ ⌊cá thường / 2⌋ (công thức bậc 1: 2 cá + 1 Gia Vị) → mua Gia Vị thiếu
      const fish = JSON.parse(ev(`JSON.stringify(bag.filter(b=>b&&b.job==='fish'&&(b.q??1)<3).map(b=>b.count||1))`) || '[]'), dishes = fish.reduce((a, c) => a + Math.floor(c / 2), 0);
      const spice = ev(`bag.reduce((a,b)=>a+(b&&b.name==='Gia Vị'?b.count||1:0),0)`) || 0;
      if (dishes > spice) {
        let p = await chef('Shop'); const need = dishes - spice;
        const add = p.match(/\[(e\d+)\] Add 1 Spice/); if (add) for (let i = 1; i < need; i++) await G('click ' + add[1]);
        p = await P(); const buy = p.match(/Spice · in bag[\s\S]*?\[(e\d+)\] Buy/); if (buy) { await G('click ' + buy[1]); await sleep(1200); L('mua ' + need + ' Gia Vị'); }
        await closeAll();
      }
      let cooked = 0;
      for (const tab of ['Grill', 'Stew', 'Soup', 'Pastry', 'Specialty']) {
        let p = await chef('Cooking'); const t = p.match(new RegExp('\\[(e\\d+)\\] ' + tab + ' ·')); if (!t) { await closeAll(); continue; }
        await G('click ' + t[1]); await sleep(1200); p = await P();
        const r = p.match(/\[(e\d+)\] [^\n]*can cook (\d+)/); if (!r || +r[2] < 1) { await closeAll(); continue; } // dòng thật: "… · Tier 1 · EXP 100% can cook 9 ✓"
        await G('click ' + r[1]); await sleep(1000); p = await P();
        const add = p.match(/\[(e\d+)\] Add 1 batch/); if (add) for (let i = 1; i < +r[2]; i++) await G('click ' + add[1]);
        p = await P(); const ck = p.match(/\[(e\d+)\] Cook ×(\d+)/); if (!ck) { await closeAll(); continue; }
        await G('click ' + ck[1]); await sleep(800); COOKRUN(0);
        for (let i = 0; i < 120 && !(window.__cook && __cook.done); i++) await sleep(1000);
        L('nấu ' + tab + ' ×' + ck[2] + ': ' + (__cook.log.slice(-1)[0] || '')); cooked += +ck[2];
        ev(`(document.querySelector('.job_fire [data-close]')||{click(){}}).click()`); await sleep(800); await closeAll();
      }
      L('nấu tổng ' + cooked + ' mẻ · Sức còn ' + Math.round(sta()));
      // hái thuốc + khảo cổ cùng ở Đồi Gió Nhẹ (bụi/vùng bậc 1, sát Elmbrook) — đàn TRONG THÀNH trước khi đi (cần ≥ 8′ Hứng Khởi; ngoài map dễ bị quái ngắt) → về Elmbrook chưng cất
      const field = opt.herbMap || 'doigio', fieldSta = (sta() >= 12 ? 1.5 * herbN : 0) + (sta() >= 20 ? 7 * digN : 0);
      if (fieldSta) L('Hứng Khởi (trước khi ra đồi): ' + await INSP.need(fieldSta, 480));
      if (herbN && sta() >= 12 && typeof HERBRUN === 'function') {
        HERBRUN(herbN, field); for (let i = 0; i < 200 && !(window.__hr && __hr.done); i++) await sleep(3000); L('hái thuốc: ' + ((__hr.log.slice(-1)[0]) || '').slice(6, 90));
      }
      for (let d = 0; d < digN && sta() >= 20 && typeof DIGRUN === 'function'; d++) { // 1 lần = 3 dò + 1 đào = 7 Sức gốc (5,6 khi có Hứng Khởi)
        DIGRUN(field); for (let i = 0; i < 200 && !(window.__dg && __dg.done); i++) await sleep(3000); L('khảo cổ: ' + ((__dg.log.slice(-1)[0]) || '').slice(9, 120));
      }
      if (ev('MAP_ID') !== 'elmbrook') for (let i = 0; i < 90 && ev('MAP_ID') !== 'elmbrook'; i++) { if (!ev('!!hero.goal')) { if (window.AP && AP.portalOk) await AP.portalOk(); await Promise.race([G('auto off', 'go ' + MAPNAME('elmbrook')), sleep(15000)]); } await sleep(4000); }
      if (ev('ECO.eco().job.brew') && typeof ALCHRUN === 'function' && ev('MAP.kind') === 'town' && ev(`npcs.some(n=>n.id==='alchemist')`)) L('chế dược: ' + await ALCHRUN());
    } catch (e) { if (e) L('lỗi ' + (e.message || e)); }
    D.done = true;
  })();
  return 'JOBDAY chạy nền';
};

// ---- GOBWATCH: canh Yêu Tinh Kho Báu ĐỘC LẬP với AP (người dùng nhắc 2026-10-27: AP đang bận việc dài — đi đường, nghề, Bí Cảnh — thì bỏ qua yêu tinh).
// Mỗi 1 s: map luyện công có quái m.gob còn sống (mọi khoảng cách trong tầm mạng) → window.__gobHunt; trong lúc săn, G() của mọi việc khác ĐỢI (trừ lệnh 'use' — uống bình)
// → bám 'attack q<id>' mỗi 2,5 s, tối đa 120 s / con. Gọi lại an toàn (1 vòng duy nhất qua window.__gobW).
window.GOBWATCH = () => {
  const ev = s => { try { return frames[0].eval(s); } catch (e) { return undefined; } };
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const L = m => { if (window.AP && AP.log) { AP.log.push(new Date().toTimeString().slice(0, 5) + ' ' + m); if (AP.log.length > 80) AP.log.shift(); } };
  if (!window.G.__gw) { window.__G0 = window.G; const wg = async (...c) => { const t0 = Date.now(); while (window.__gobHunt && !/^use /.test(String(c[0] || '')) && Date.now() - t0 < 150e3) await sleep(400); return window.__G0(...c); }; wg.__gw = 1; window.G = wg; } // nạp lại helper.js định nghĩa lại G → bọc lại
  if (window.__gobW) return 'GOBWATCH đang chạy';
  const W = window.__gobW = { on: true, done: {}, n: 0 };
  (async () => {
    while (W.on) {
      await sleep(1000);
      try {
        if (ev('MAP.kind') !== 'field' || ev('MAP.mode') === 'bicanh' || ev('hero.dead')) { window.__gobHunt = null; continue; }
        const g = JSON.parse(ev(`JSON.stringify((()=>{const g=mobs.filter(m=>m.gob&&!m.dead&&m.hp>0).sort((a,b)=>Math.hypot(a.x-hero.x,a.y-hero.y)-Math.hypot(b.x-hero.x,b.y-hero.y))[0];return g?{id:g.id,x:g.x,y:g.y,hp:Math.round(100*g.hp/g.maxHp)}:null})())`) || 'null');
        const H = window.__gobHunt;
        if (H && Date.now() - H.t > 150e3) { W.done[H.id] = 1; window.__gobHunt = null; L('yêu tinh: quá 150 s — bỏ (phanh cứng)'); continue; }
        if (!g) { if (H) { L('yêu tinh: ' + (H.hp <= 5 ? 'HẠ ĐƯỢC' : 'biến mất') + ' sau ' + Math.round((Date.now() - H.t) / 1000) + ' s'); W.done[H.id] = 1; window.__gobHunt = null; } continue; }
        if (W.done[g.id]) continue;
        const myHp = ev('hero.hp/hero.maxHp') || 0, hx = ev('hero.x'), hy = ev('hero.y');
        if (!H || H.id !== g.id) { if (myHp < 0.5) continue; window.__gobHunt = { id: g.id, t: Date.now(), hp: g.hp, at: 0, x0: hx, y0: hy }; W.n++; L('THẤY yêu tinh kho báu → đánh ngay (GOBWATCH)'); }
        const h = window.__gobHunt; h.hp = g.hp;
        // phanh an toàn (Brokk gục 10:35 ngày 27 khi đuổi yêu tinh vào bãi mạnh): máu < 35% · xa chỗ bắt đầu > 900 px · quá 60 s → bỏ
        const why = myHp < 0.35 ? 'máu thấp' : Math.hypot(hx - h.x0, hy - h.y0) > 900 ? 'chạy quá xa' : Date.now() - h.t > 60e3 ? 'quá 60 s' : '';
        if (why) { W.done[g.id] = 1; window.__gobHunt = null; L('yêu tinh: bỏ đuổi (' + why + ')'); continue; }
        if (Date.now() - h.at > 2500) {
          h.at = Date.now();
          // G có thể KHÔNG BAO GIỜ trả về khi API bị pause (người chơi bấm tay) → kẹt __gobHunt → mọi lệnh G khác chờ mãi (13:21–13:34 ngày 27) → luôn đặt hạn 10 s
          const G10 = c => Promise.race([__G0(c), sleep(10000).then(() => '')]);
          const l = String(await G10('look')), q = (l.match(/Monsters[^\n]*/) || [''])[0].match(/(?:Goblin|Yêu Tinh|Yêu tinh)[^:]*: (q\d+)/i);
          if (q) await G10('attack ' + q[1]); else await G10('go ' + Math.round(g.x / 10) + ',' + Math.round(g.y / 10));
          if (!ev('AUTO.on')) await G10('auto on');
          if (window.AP) AP.state = 'SĂN YÊU TINH (' + g.hp + '%)';
        }
      } catch (e) {}
    }
  })();
  return 'GOBWATCH bật';
};
GOBWATCH();

// ---- PLAYRUN: Diễn Tấu (nhịp 4 làn D F J K). PLAY.notes() = [{at, l, st}], PLAY.state().rg.t = giây trong bài → bấm phím làn khi nốt tới (−40..+15 ms).
// Lần đầu 2026-10-27: 92/92 Sublime → Cảm hứng Sublime (−20% Sức Nghề, +20% EXP nghề, 20′ ở bậc 1) cho mình + người đứng gần; 3 Sức/bài, +45 EXP Diễn Tấu.
// Gọi SAU khi đã bấm "Bắt đầu diễn" (PLAY.open('mus') → nút "Bắt đầu diễn"). Phải đứng yên, ngoài giao tranh. Phím J/K/F còn mở bảng khác (Thú cưỡi…) — đóng sau bài.
window.PLAYRUN = () => {
  const W = () => frames[0], R = window.__pr = { log: [], done: false, hits: 0 };
  const key = c => { W().dispatchEvent(new (W().KeyboardEvent)('keydown', { code: c, key: c.slice(3).toLowerCase(), bubbles: true })); W().dispatchEvent(new (W().KeyboardEvent)('keyup', { code: c, key: c.slice(3).toLowerCase(), bubbles: true })); };
  (async () => {
    const P = W().PLAY; for (let i = 0; i < 50 && !P.state().rg; i++) await new Promise(r => setTimeout(r, 100));
    if (!P.state().rg) { R.log.push('không vào bài'); R.done = true; return; }
    const done = new Set();
    while (true) {
      const s = P.state().rg; if (!s) break; const t = s.t;
      // chấm Tuyệt trong ±45 ms (SETTINGS.job.play.judge); khi trang ẩn PUMP bơm 25 khung/s → t nhảy 40 ms/bước → bấm ngay khi nốt vào [−40, +15] ms
      for (const [i, n] of P.notes().entries()) if (n.st < 0 && !done.has(i) && n.at - t < 0.015 && n.at - t > -0.04) { done.add(i); key(['KeyD', 'KeyF', 'KeyJ', 'KeyK'][n.l]); R.hits++; }
      if (t > s.dur + 0.5) break;
      await new Promise(r => setTimeout(r, 4));
    }
    await new Promise(r => setTimeout(r, 2500));
    R.log.push(W().eval(`[...document.querySelectorAll('.play_res,.mg_res,.job_res')].map(e=>e.innerText).join(' ').replace(/\\s+/g,' ').slice(0,200)`)); R.done = true;
  })();
  return 'PLAYRUN';
};
// Đàn 1 bài (bài bậc cao nhất đã có) → chờ xong → đóng bảng. Trả kết quả chữ.
window.PERFORM = async () => {
  const W = () => frames[0], sleep = ms => new Promise(r => setTimeout(r, ms));
  await G('auto off'); W().PLAY.open('mus'); await sleep(2000);
  const p = String(await G('look')).split('Open panels:')[1] || '', b = p.match(/\[(e\d+)\] Bắt đầu diễn(?! ⊘)/); if (!b) return 'không có nút Bắt đầu diễn';
  await G('click ' + b[1]); PLAYRUN(); for (let i = 0; i < 120 && !__pr.done; i++) await sleep(1000);
  for (let i = 0; i < 4; i++) { const r = await G('close'); if (/No panel/.test(r)) break; }
  return (__pr.log[0] || '').slice(0, 80);
};
// ---- INSP: giữ Hứng Khởi khi sắp tiêu Sức Nghề (eco_core.js inspOn/staCut + settings play.insp, đọc 2026-10-27).
// Bài hạng Tuyệt (≥ 85% nốt) → Sức Nghề −20% (hạng 2 −15%, hạng 1 −10%) cho MỌI nghề tốn Sức (câu 2 · hái 1,5 (×1,5 thảo dược, tin #29) · dò 1 · đào 4 · rượu 3 · gieo 1 · gặt 2 · ong 3)
// + EXP mọi nghề +20% (cả nấu/chế dược 0 Sức); kéo dài 20′ (bài bậc 1) → 40′ (bậc 10); bài mới THAY bài cũ; Trà Tập Trung cộng dồn, trần −35%.
// 1 bài = 3 Sức (2,4 nếu đang có Hứng Khởi) → chỉ đàn khi việc sắp làm trong cửa sổ tốn ≥ 12 Sức gốc (hoà vốn 12–15). Đàn cũng lên nghề Diễn Tấu → bài bậc cao → cửa sổ dài hơn.
window.INSP = {
  left() { try { return frames[0].eval(`(()=>{const i=((ECO.eco()||{}).job||{}).insp, n=(typeof API!=='undefined'&&API.now)?API.now():Date.now(); return i&&i.end>n?Math.round((i.end-n)/1000):0})()`) || 0; } catch (e) { return 0; } },
  async need(sta = 12, min = 120) {
    if (!frames[0].eval('!!(ECO.eco()||{}).job&&!!ECO.eco().job.music')) return 'chưa học Diễn Tấu';
    const l = INSP.left(); if (l >= min) return 'còn ' + Math.round(l / 60) + '′';
    if (sta < 12) return 'không đáng đàn (' + sta + ' Sức gốc)';
    const r = await PERFORM(); return 'đàn: ' + r + ' → còn ' + Math.round(INSP.left() / 60) + '′';
  },
};

// ---- HERBRUN(n, mapId): hái n bụi thảo dược ĐÚNG BẬC (bụi bậc = bậc map; Hái Thuốc bậc 1 → map 0x quanh Elmbrook, vd 'donglua').
// Bụi chỉ thấy trong tầm nhìn (HERB.list()) → đi vòng các trại quái (MAP.zones[].camps) để dò; hái 3 s (HERB.go), bị đánh là ngắt. 1 Sức/lần. Nền: window.__hr.
window.HERBRUN = (n = 20, mapId = 'donglua') => {
  const w = () => frames[0], ev = s => { try { return w().eval(s); } catch (e) { return undefined; } };
  const H = window.__hr = { log: [], done: false, got: 0 }, L = m => { H.log.push(new Date().toTimeString().slice(0, 5) + ' ' + m); if (H.log.length > 30) H.log.shift(); };
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  (async () => {
    try {
      for (let i = 0; i < 120 && ev('MAP_ID') !== mapId; i++) { if (!ev('!!hero.goal')) { if (window.AP && AP.portalOk) await AP.portalOk(); await Promise.race([G('auto off', 'go ' + MAPNAME(mapId)), sleep(15000)]); } await sleep(4000); }
      if (ev('MAP_ID') !== mapId) { L('không tới được ' + mapId); throw 0; }
      await G('auto off');
      const tier = Math.floor(((ev('ECO.eco().job.herb.lv') || 1) - 1) / 10) + 1, bad = {};
      const camps = JSON.parse(ev(`JSON.stringify((MAP.zones||[]).flatMap(z=>z.camps.map(c=>[Math.round(c.x/10),Math.round(c.y/10)])))`) || '[]');
      let ci = 0; const t0 = Date.now();
      while (H.got < n && Date.now() - t0 < 6 * 60e3) {
        const sv = ev('ECO.eco().job.sta.v'); if (sv == null || !w().HERB) { await sleep(1000); continue; } // map đang tải → đọc rỗng, đừng tưởng hết Sức
        if (sv < 1.5) { L('hết Sức Nghề'); break; }
        const hx = ev('hero.x'), hy = ev('hero.y');
        const b = (w().HERB.list() || []).filter(b => !b.busy && (bad[b.id] || 0) < 2 && (b.t || 1) <= tier).sort((a, c) => Math.hypot(a.x - hx, a.y - hy) - Math.hypot(c.x - hx, c.y - hy))[0];
        if (!b) { const c = camps[ci++ % Math.max(1, camps.length)]; if (!c) break; await G('go ' + c[0] + ',' + c[1], 'wait arrived 20'); continue; }
        // quái đang giao chiến gần → dọn sạch TRƯỚC rồi mới hái (bị đánh trúng là ngắt hái → trước đây bỏ bụi, đánh quái, rồi lặp lại — người dùng thấy vòng lặp 2026-10-27)
        const fighting = () => +ev(`mobs.filter(m=>!m.dead&&m.hp>0&&m.state==='fight'&&Math.hypot(m.x-hero.x,m.y-hero.y)<320).length`) || 0;
        if (fighting()) { await G('auto on'); for (let k = 0; k < 25 && fighting(); k++) await sleep(1000); await G('auto off'); await sleep(500); continue; }
        const xp0 = ev('ECO.eco().job.herb.xp') + 1000 * ev('ECO.eco().job.herb.lv');
        w().HERB.go(b.id); let t = Date.now(); while (!w().HERB.busy() && Date.now() - t < 8000) await sleep(150);
        t = Date.now(); while (w().HERB.busy() && Date.now() - t < 9000) await sleep(200);
        await sleep(400);
        if (ev('ECO.eco().job.herb.xp') + 1000 * ev('ECO.eco().job.herb.lv') !== xp0) { H.got++; }
        else if (fighting()) { /* bị quái ngắt → vòng sau dọn quái rồi hái lại đúng bụi này */ }
        else bad[b.id] = (bad[b.id] || 0) + 1; // hụt không do quái: thử lại 1 lần, hụt 2 lần mới bỏ
      }
      L('hái được ' + H.got + ' · Hái Thuốc cấp ' + ev('ECO.eco().job.herb.lv') + ' · túi: ' + ev(`JSON.stringify(bag.filter(b=>b&&b.job&&b.job!=='fish').map(b=>b.name+':'+(b.count||1)))`));
    } catch (e) { if (e) L('lỗi ' + (e.message || e)); }
    H.done = true;
  })();
  return 'HERBRUN chạy nền';
};

// ---- ALCHRUN: Chế Dược ở Bàn Chưng Cất (Nhà Giả Kim → "Distillation Table"): mỗi thuốc "can make N" → chọn → Add batch tới N → "Distill ×N" (5 s/mẻ, 0 Sức Nghề, 20 EXP/mẻ).
// Lần đầu 2026-10-27: 1 mẻ Mồi Câu Thơm (1 Cỏ Mật Ong + 1 Hoa Gió) → 5 mồi. Cỏ Mật Ong hiếm (1/23 lần hái bậc 1) → nút thắt. Bình Rỗng mua ở Nhà Giả Kim (tab Buy).
window.ALCHRUN = async () => {
  const W = () => frames[0], sleep = ms => new Promise(r => setTimeout(r, ms)), P = async () => (String(await G('look')).split('Open panels:')[1] || '');
  const out = [];
  for (let k = 0; k < 6; k++) {
    W().eval(`talkTo(npcs.find(n=>n.id==='alchemist'))`); await sleep(3000);
    let p = await P(); const d = p.match(/\[(e\d+)\] Distillation Table/); if (!d) { out.push('không thấy Bàn Chưng Cất'); break; }
    await G('click ' + d[1]); await sleep(2000); p = await P();
    const r = p.match(/\[(e\d+)\] ([^\n·]+) · [^\n]*can make (\d+)/); if (!r) break;
    await G('click ' + r[1]); await sleep(1000); p = await P();
    const add = p.match(/\[(e\d+)\] Add 1 batch(?! ⊘)/); if (add) for (let i = 1; i < Math.min(10, +r[3]); i++) await G('click ' + add[1]);
    p = await P(); const b = p.match(/\[(e\d+)\] Distill ×(\d+)(?! ⊘)/); if (!b) break;
    await G('click ' + b[1]); await sleep(5200 * +b[2] + 2500); out.push(r[2].trim() + ' ×' + b[2]);
    for (let i = 0; i < 3; i++) { const c = await G('close'); if (/No panel/.test(c)) break; }
  }
  for (let i = 0; i < 3; i++) { const c = await G('close'); if (/No panel/.test(c)) break; }
  return out.join(', ') || 'không đủ nguyên liệu';
};

// ---- TRAVEL(mapId): đi tới map (gọi lại `go` mỗi khi đứng yên sau khi qua cổng; tự bấm hộp "Leave …? Go"). Nền: window.__tr {log, done}.
