// ---- DIGRUN(mapId): Khảo Cổ. Vùng khảo cổ chỉ biết khi đứng trong (DIG.state().zone, máy chủ gửi tin 'dz') → đi vòng trại quái tới khi vào vùng →
// Que Dò (phím Q, trùng thì T; 1 Sức) → vòng mũi tên 8 hướng (.dig_probe .arw rotate(k·45), 0 = Đông, theo chiều kim đồng hồ) + Lạnh/Ấm/Nóng → đi theo mũi tên
// (Lạnh 300 px · Ấm 150 · Nóng 60) → có dấu (DIG.state().site) → tới ≤ near → phím E đào (4 Sức, đứng yên, bị đánh là ngắt). Nền: window.__dg.
window.DIGRUN = (mapId = 'doigio') => {
  const w = () => frames[0], ev = s => { try { return w().eval(s); } catch (e) { return null; } };
  const D = window.__dg = { log: [], done: false }, L = m => { D.log.push(new Date().toTimeString().slice(0, 8) + ' ' + m); if (D.log.length > 40) D.log.shift(); };
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const key = c => { w().dispatchEvent(new (w().KeyboardEvent)('keydown', { code: c, key: c.slice(3).toLowerCase(), bubbles: true })); w().dispatchEvent(new (w().KeyboardEvent)('keyup', { code: c, key: c.slice(3).toLowerCase(), bubbles: true })); };
  const S = () => (w().DIG ? w().DIG.state() : {});
  (async () => {
    try {
      for (let i = 0; i < 90 && ev('MAP_ID') !== mapId; i++) { if (ev('MAP_ID') && !ev('!!hero.goal')) { if (window.AP && AP.portalOk) await AP.portalOk(); await Promise.race([G('auto off', 'go ' + MAPNAME(mapId)), sleep(15000)]); } await sleep(4000); }
      await G('auto off');
      // vùng = elip r 420 × ry 240 px ở chỗ ngẫu nhiên (không theo trại quái) → quét lưới ~700 × 400 px trên cả map (world.w × world.h)
      const ww = ev('world.w') || 3072, wh = ev('world.h') || 2304, grid = [];
      for (let y = 250, row = 0; y < wh; y += 420, row++) { const xs = []; for (let x = 400; x < ww; x += 700) xs.push([Math.round(x / 10), Math.round(y / 10)]); grid.push(...(row % 2 ? xs.reverse() : xs)); }
      for (let i = 0; i < grid.length && !S().zone; i++) { await G('go ' + grid[i][0] + ',' + grid[i][1], 'wait arrived 25'); await sleep(1200); }
      if (!S().zone) { L('không tìm thấy vùng khảo cổ'); throw 0; }
      L('vào vùng khảo cổ: ' + JSON.stringify(S().zone).slice(0, 120));
      for (let k = 0; k < 12 && !S().site; k++) {
        const left = S().left; if (!left) { L('hết lượt dò'); break; }
        key('KeyQ'); await sleep(1500); let r = S().ring; if (!r) { key('KeyT'); await sleep(1500); r = S().ring; }
        if (!r) { L('không dò được (phím?)'); break; }
        const tr = ev(`(document.querySelector('.dig_probe .arw')||{getAttribute(){return ''}}).getAttribute('transform')`) || '', a = (+((tr.match(/rotate\((-?\d+)/) || [])[1] || 0)) * Math.PI / 180;
        const heat = /hot/.test(r.cls) ? 'hot' : /warm/.test(r.cls) ? 'warm' : 'cold', step = { hot: 60, warm: 150, cold: 300 }[heat];
        L('dò: ' + r.txt + ' hướng ' + Math.round(a * 180 / Math.PI) + '° (còn ' + left + ')');
        if (S().site) break;
        const nx = Math.round((ev('hero.x') + Math.cos(a) * step) / 10), ny = Math.round((ev('hero.y') + Math.sin(a) * step) / 10);
        await G('go ' + nx + ',' + ny, 'wait arrived 15'); await sleep(800);
      }
      const s = S().site; if (!s) { L('chưa ra chỗ đào'); throw 0; }
      await G('go ' + Math.round(s.x / 10) + ',' + Math.round(s.y / 10), 'wait arrived 15'); await sleep(800);
      const lv0 = ev('ECO.eco().job.dig.lv'), xp0 = ev('ECO.eco().job.dig.xp');
      key('KeyE'); await sleep(1200);
      for (let i = 0; i < 30 && S().cast; i++) await sleep(1000);
      await sleep(1500);
      L('đào xong: ' + ev(`[...document.querySelectorAll('.mg_res,.dig_res,.job_res')].map(e=>e.innerText).join(' ').replace(/\\s+/g,' ').slice(0,180)`) + ' · Khảo Cổ ' + lv0 + '→' + ev('ECO.eco().job.dig.lv') + ' xp ' + xp0 + '→' + ev('ECO.eco().job.dig.xp'));
    } catch (e) { if (e) L('lỗi ' + (e.message || e)); }
