};

// ---- RACE(n): Đua Thời Gian ở Trường Đua Gió (Trọng Tài `trongtai`, Kinh đô 142,170 — world_mg_m6.js + lõi tất định mg_m6_core.js; máy chủ CHẠY LẠI chuỗi nhập liệu).
// 2 vòng, giới hạn 180 s, vé 0,01 × G(cấp) vàng, mọi thú cùng tốc độ ("thắng nhờ tay lái"), +5 Năng Động. Lái = bộ lái máy của chính lõi (core.ai, sk 1) chạy trên
// BẢN SAO trạng thái xe mỗi mẫu (30 lần/giây) → {thr, brk, steer −1…1, boost} như người giữ chuột lái; lạc đường > 1,5 s → R (về đường). Không tính trước / không sửa chuỗi nộp.
// Gọi khi AP đã dừng + đứng ở Kinh đô. Nền: window.__race {log, done}.
window.RACE = (n = 1) => {
  const w = () => frames[0], ev = s => { try { return w().eval(s); } catch (e) { return undefined; } };
  const X = window.__race = { log: [], done: false, best: null }, L = m => { X.log.push(new Date().toTimeString().slice(0, 8) + ' ' + m); if (X.log.length > 30) X.log.shift(); };
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const P = async () => String(await G('look')).split('Open panels:')[1] || '';
  const S = () => { try { return w().MG6.state() || {}; } catch (e) { return {}; } };
  function drive() {
    const K = w().MG6.core(), dt = K.RATE * K.DT, M = { sk: 1, lane: 0, laneC: 0, dg: {}, rng: K.rng(7), react: 0 };
    let lostT = 0;
    w().MG6.drive(R => {
      const r = R.r, s = Object.assign({}, r, M), c = K.ai(R.T, R.W, s, dt);
      for (const k of ['laneC', 'wt', 'dg', 'smart', 'holdT', 'waitT', 'react']) M[k] = s[k];
      let back = false; if (r.off > K.HW + 50) { lostT += dt; if (lostT > 1.5) { back = true; lostT = 0; } } else lostT = 0;
      return { thr: c.thr, brk: c.brk, steer: c.steer, boost: c.boost, back };
    });
  }
  (async () => {
    try {
      if (ev('MAP_ID') !== 'aurelion') { L('cần đứng ở Kinh đô'); throw 0; }
      let p = '';
      if (!/pick|res/.test(S().phase || '')) { // bảng đua chưa mở → tới Trọng Tài → "Time Trial"
        await G('auto off', 'go 140,172', 'wait arrived 30'); ev(`talkTo(npcs.find(n=>n.id==='trongtai'))`); await sleep(3000);
        p = await P(); const tt = p.match(/\[(e\d+)\] Time Trial/); if (tt) { await G('click ' + tt[1]); await sleep(4000); }
      }
      for (let k = 0; k < n; k++) {
        for (let i = 0; i < 20 && !/pick|res/.test(S().phase || ''); i++) await sleep(500);
        p = await P(); const go = p.match(/\[(e\d+)\] (?:Race again|Race ·|Vào đua|Đua lại)[^\n]*/); // nhãn thật: "[e16] Race · 335 gold Enter"
        if (!go) { L('không thấy nút vào đua — ' + p.replace(/\s+/g, ' ').slice(0, 120)); break; }
        await G('click ' + go[1]);
        for (let i = 0; i < 40 && !/count|race/.test(S().phase || ''); i++) await sleep(250);
        if (!/count|race/.test(S().phase || '')) { L('không vào được đua (phase ' + S().phase + ')'); break; }
        drive(); L('lượt ' + (k + 1) + ': xuất phát · ' + go[0].replace(/\[e\d+\] /, '').slice(0, 40));
        for (let i = 0; i < 400 && !(S().r && S().r.done) && S().phase !== 'res'; i++) await sleep(500);
        await sleep(3000);
        const st = S(), fin = st.r && st.r.fin; if (fin && (!X.best || fin < X.best)) X.best = fin;
        L('lượt ' + (k + 1) + ': ' + (st.r && st.r.done ? 'về đích ' + fin.toFixed(2) + ' s' : 'không về đích') + ' · ' + JSON.stringify(st.out || '').slice(0, 120));
      }
      p = await P(); const lv = p.match(/\[(e\d+)\] Leave\b/); if (lv) await G('click ' + lv[1]); else await G('close');
    } catch (e) { if (e) L('lỗi ' + (e.message || e)); }
    X.done = true;
  })();
  return 'RACE chạy nền — xem __race.log';
};

// ---- ENHALL(cap, reserve): cường hoá ĐỀU 10 ô của tướng chính (cường hoá theo Ô, không theo món — đổi đồ giữ số +; người dùng dặn 2026-10-27 "nâng đều hết").
// Mỗi lượt chọn ô có + thấp nhất (< cap) → Thợ rèn "Enhance slot" → tướng → ô → "Enhance". Dừng khi đủ cap / vàng sau lượt < reserve / thiếu Huyền Thiết.
// Bảng (SETTINGS.smith): tỉ lệ +1..+3 100% · +4 90% · +5 80% · +6 70% và hỏng TỤT 1 cấp → cap ≤ 5 an toàn. Giá [HT, vàng] = smith.cost[+hiện tại].
// Phải đứng ở thị trấn có Thợ rèn (AP dừng). Nền: window.__enh {log, done}.
window.ENHALL = (cap = 4, reserve = 40000) => {
  const w = () => frames[0], ev = s => { try { return w().eval(s); } catch (e) { return undefined; } };
  const E = window.__enh = { log: [], done: false, n: 0 }, L = m => { E.log.push(new Date().toTimeString().slice(0, 5) + ' ' + m); if (E.log.length > 40) E.log.shift(); };
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const P = async () => String(await G('look')).split('Open panels:')[1] || '';
  const SLOTS = { weapon: 'Weapon', helm: 'Helm', armor: 'Armor', gloves: 'Gloves', belt: 'Belt', boots: 'Boots', neck: 'Necklace', ring1: 'Ring', ring2: 'Ring', jade: 'Jade Pendant' };
  (async () => {
    try {
      const id = ev(`Object.keys(EQUIP).filter(c=>carry.includes(c)).sort((a,b)=>lvlOf(b)-lvlOf(a))[0]`), name = ev(`CHS['${id}'].name`);
      await AP.talkId('smith'); await sleep(1500);
      let p = await P(); const t = p.match(/\[(e\d+)\] Enhance slot/); if (t) { await G('click ' + t[1]); await sleep(1500); p = await P(); }
      const c = p.match(new RegExp('\\[(e\\d+)\\] ' + name + ' ·')); if (c && !/is now active ✓/.test(c[0])) { await G('click ' + c[1]); await sleep(1200); }
      for (let k = 0; k < 80; k++) {
        const plus = JSON.parse(ev(`JSON.stringify((ECO.eco().plus||{})['${id}']||{})`) || '{}'), cost = ev('SETTINGS.smith.cost');
        const s = Object.keys(SLOTS).sort((a, b) => (plus[a] || 0) - (plus[b] || 0))[0], cur = plus[s] || 0;
        if (cur >= cap) { L('xong: mọi ô ≥ +' + cap); break; }
        const [ht, gold] = cost[cur];
        if (ev('PLAYER.gold') - gold < reserve) { L('dừng: giữ ' + reserve + ' vàng (còn ' + ev('PLAYER.gold') + ')'); break; }
        if (ev('ECO.eco().iron') < ht) { L('dừng: thiếu Huyền Thiết'); break; }
        p = await P();
        // chọn dòng có ĐÚNG số + của ô (2 Nhẫn: cùng số + thì gộp 1 dòng "[eA–eB] Ring +0 … ×2", khác thì 2 dòng — 27/10 lấy dòng đầu → Nhẫn 1 bị nâng 5 lần)
        const m = p.match(new RegExp('\\[(e\\d+)(?:–e\\d+)?\\] ' + SLOTS[s] + ' \\+' + cur + ' ')); if (!m) { L('không thấy nút ô ' + s + ' +' + cur); break; }
        await G('click ' + m[1]); await sleep(1000);
        p = await P(); const b = [...p.matchAll(/\[(e\d+)\] Enhance(?! slot| ⊘)\s*$/gm)].pop(); if (!b) { L('không thấy nút Enhance (' + s + ')'); break; }
        await G('click ' + b[1]); await sleep(1800); E.n++;
        const now = (JSON.parse(ev(`JSON.stringify((ECO.eco().plus||{})['${id}']||{})`) || '{}')[s]) || 0;
        L(name + ' ' + s + ' +' + cur + ' → ' + (now > cur ? '+' + now : 'hụt') + ' · vàng ' + ev('PLAYER.gold'));
      }
      for (let i = 0; i < 4; i++) { const r = await G('close'); if (/No panel/.test(r)) break; }
    } catch (e) { L('lỗi ' + (e.message || e)); }
    E.done = true;
  })();
  return 'ENHALL chạy nền — xem __enh.log';
};

// ---- VQRUN: Chiến Trường Vạn Quân (13:00 · 21:00 giờ game = 17:00 · 01:00 máy; sảnh mở trước 10′, trận 20′, vào muộn tới :13). Tin #28 (27/10): EXP tham gia MỖI PHÚT ở trận
// (cần ≥ 10 điểm: chiếm cờ +20 · hạ người +10), không cần Giờ treo, + rương ×2. Kinh đô Tướng Quân `warlord` 208,68 → "Go to Rear Camp" (map 'songky' 6144×4096).
// Phe = trại gần chỗ xuất hiện (bm tây 406,2028 · hh đông 5738,2028). Khai chiến → tới cờ NGOÀI gần nhất (N 3318,860 · S 2888,2765; r 150; cờ Trung 3072,2032 tranh nhiều) → Auto, đứng trong vòng.
// Gục → sống lại ở trại → quay lại cờ. Hết trận (bị trả về / map đổi) hoặc 24′ → dừng. AP phải dừng. Nền: window.__vq {log, done}.
window.VQRUN = () => {
