        await G('auto off', 'go 206,70', 'wait arrived 30'); ev(`talkTo(npcs.find(n=>n.id==='warlord'))`); await sleep(3500);
        let p = await P(); const sv = p.match(/\[(e\d+)\] Battle of Myriads · Rear Camp/); if (sv) { await G('click ' + sv[1]); await sleep(3000); p = await P(); } // hộp thoại → mục dịch vụ → sảnh
