// Eldoria AUTOPILOT — máy trạng thái chạy trong trang ngoài, KHÔNG cần LLM cho việc lặp lại.
// Cần helper.js + gear.js đã nạp. API: AP.start() · AP.stop() · AP.report() (≤ 12 dòng) · AP.cfg
// Nguyên tắc: tôn trọng người chơi (paused → đứng chờ), không chat, không tiêu Ruby, không vào map đỏ/đen trừ khi cfg.red.
(() => {
  if (window.AP && window.AP.on) window.AP.stop(); // window.AP: tránh TDZ của const AP bên dưới
  const AP = window.AP = {
    on: false, log: [], state: 'idle', stuck: '', deaths: 0, since: Date.now(),
    cfg: { gearEvery: 240e3, red: false, yellow: true, trainGap: 3, hpPot: 0.35, maxStuckMin: 10 }, // yellow: từ cấp 51 hết map xanh hợp cấp (27/10; người dùng cho AI vào map đỏ/đen)
    k: {}, // bộ nhớ tạm theo bước
  };
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const L = m => { AP.log.push(new Date().toTimeString().slice(0, 5) + ' ' + m); if (AP.log.length > 80) AP.log.shift(); };
  const W = () => frames[0];
  const ev = s => { try { return W().eval(s); } catch (e) { return undefined; } };
  const mp = () => ev('MAP_ID') || '';
  const ready = () => !!(W() && W().ZY_AGENT && ev('typeof hero!=="undefined"&&!!hero&&!!hero.st'));
  const champs = () => JSON.parse(ev(`JSON.stringify(Object.keys(EQUIP).filter(c=>carry.includes(c)).map(c=>({id:c,name:CHS[c].name,lv:lvlOf(c)})))`) || '[]'); // chỉ tướng MANG THEO (27/10: Nerissa ngoài đội bị chọn ra trận — không có nút trạng thái nên luôn "còn đứng")
  const active = () => ev('active');
  const fallen = name => { const b = [...W().document.querySelectorAll('button.cpip')].find(e => e.getAttribute('aria-label').startsWith(name)); return b ? /fallen/.test(b.getAttribute('aria-label')) : false; };
  const mapLv = id => ev(`(MANIFEST.maps['${id}']||{}).level`) || null;
  const mapColor = id => ev(`(MANIFEST.maps['${id}']||{}).color`) || '';

  // ---- di chuyển ----
  async function goMap(id) {
    if (mp() === id) return true;
    if (AP.k.travel !== id || Date.now() - (AP.k.travelT || 0) > 120e3) {
      AP.k.travel = id; AP.k.travelT = Date.now();
      (AP.portalOk && await AP.portalOk()), await G('auto off', 'go ' + MAPNAME(id)); L('đi tới map ' + id); // hộp "Leave …? Go" chặn tự đi
    }
    return false;
  }
  async function arrivedFresh() { // đóng popup tin tức sau khi vào map
    if (AP.k.closedOn !== mp() + ev('location.search')) { AP.k.closedOn = mp() + ev('location.search'); await G('close'); }
  }
  // ---- chọn bãi an toàn ----
  function camps(sp) {
    const list = JSON.parse(ev(`JSON.stringify((MAP.zones||[]).flatMap(z=>z.camps.map((c,i)=>({x:Math.round(c.x/10),y:Math.round(c.y/10),sp:campSpecies(z,c,i),lv:z.level}))))`) || '[]');
    return sp ? list.filter(c => (Array.isArray(sp) ? sp : [sp]).includes(c.sp)) : list;
  }
  function dangerNear(c, myLv) { // quái cấp cao bất thường quanh bãi
    return ev(`mobs.some(m=>!m.dead&&m.level>=${myLv + 6}&&Math.hypot(m.x/10-${c.x},m.y/10-${c.y})<35)`);
  }
  async function fightAt(sp, tag) {
    const lv = ev('lvlOf(active)') || 1;
    if (AP.k.fight !== tag) {
      const cs = camps(sp); if (!cs.length) { AP.stuck = 'không thấy bãi ' + sp + ' ở ' + mp(); return; }
      const c = cs.find(c => !dangerNear(c, lv)) || cs[0];
      AP.k.fight = tag; AP.k.camp = c;
      await G('go ' + c.x + ',' + c.y); await sleep(4000); await G('wait arrived 15', 'auto on'); L(`đánh ${tag} tại ${c.x},${c.y}`);
      return;
    }
    if (!ev('AUTO.on')) { await G('go ' + AP.k.camp.x + ',' + AP.k.camp.y, 'wait arrived 15', 'auto on'); }
  }
  // ---- luân phiên tướng ----
  function pickTrainee(zoneMin) {
    const cs = champs().filter(c => !fallen(c.name)); if (!cs.length) return null;
    cs.sort((a, b) => a.lv - b.lv);
    const hi = cs[cs.length - 1], lo = cs[0];
    if (hi.lv - lo.lv >= AP.cfg.trainGap && lo.lv >= zoneMin - 1) return lo;
    return hi;
