    const ch = await lookBtn(/\[(e\d+)\] Activity Chest/); if (ch) { await G('click ' + ch); for (let i = 0; i < 4; i++) { const c = await lookBtn(/\[(e\d+)\] Milestone \d+ chest: Claim/); if (!c) break; await G('click ' + c); } }
