    if (mp() !== home) { if (Date.now() - (AP.k2.goT || 0) > 120e3) { AP.k2.goT = Date.now(); await G('auto off', 'go ' + MAPNAME(home)); L('về thành: ' + [needBag && 'túi đầy', needPot && 'hết bình'].filter(Boolean).join(', ')); } AP.state = 'về thành'; return true; }
