// ---- luyện tướng: chỉ tướng ra trận (active) nhận EXP (gainExp) → mỗi trainEvery′ dành trainMin′ đưa tướng thấp nhất về bãi hợp cấp ----
(() => {
  const ev = s => { try { return frames[0].eval(s); } catch (e) { return undefined; } };
  const L = m => { AP.log.push(new Date().toTimeString().slice(0, 5) + ' ' + m); if (AP.log.length > 80) AP.log.shift(); };
  const team = () => JSON.parse(ev(`JSON.stringify(carry.filter(Boolean).map(c=>({id:c,n:CHS[c].name,lv:lvlOf(c),down:!!champState(c).down})))`) || '[]');
  Object.assign(AP.cfg, { trainGap2: 6, trainMin: 25, trainEvery: 60 });
  const baseExt = AP.ext;
  AP.ext = async () => (baseExt && await baseExt()) || await train();
  function pickMap(lv) {
    const ms = JSON.parse(ev(`JSON.stringify(Object.entries(MANIFEST.maps).filter(([k,m])=>m.kind==='field'&&m.level&&m.color==='green'&&k[0]!=='_').map(([k,m])=>({id:k,lv:m.level})))`) || '[]');
    const ok = ms.filter(m => m.lv[0] <= lv + 1); ok.sort((a, b) => Math.abs((a.lv[0] + a.lv[1]) / 2 - lv - 1) - Math.abs((b.lv[0] + b.lv[1]) / 2 - lv - 1)); return ok[0];
  }
  async function train() {
    const now = Date.now(); let T = AP.k2.train;
    const all = team(); if (!all.length) return !!T; // đang tải map → đọc rỗng, đừng tưởng gục
    const cs = all.filter(c => !c.down).sort((a, b) => a.lv - b.lv), hi = cs[cs.length - 1];
    if (T) { const t = cs.find(c => c.id === T.id); if (!t && (T.miss = (T.miss || 0) + 1) < 4) return true; if (t) T.miss = 0; if (now > T.until || !t || t.lv >= hi.lv - 2) { if (!t && AP.k2.trainFail) AP.k2.trainFail[T.id] = (AP.k2.trainFail[T.id] || 0) + 1; AP.k2.train = null; AP.k2.trainEnd = now; AP.k.fight = null; L('hết lượt luyện ' + T.n + (t ? ' → ' + t.lv : ' (gục)')); return false; } }
    else {
      // chỉ khi bước chính là cày cấp (level / chờ cấp st.need) — 27/10 luyện Saphra chen ngang bước goto Trạm Biên Ải 15′ · tướng gục 2 lần/ngày → thôi luyện hôm đó
      const day = ev('ECO.day()'), fails = (AP.k2.trainFail && AP.k2.trainFail.d === day) ? AP.k2.trainFail : (AP.k2.trainFail = { d: day });
      const pk = cs.find(c => (fails[c.id] || 0) < 2 && hi.lv - c.lv >= AP.cfg.trainGap2);
      if (now - (AP.k2.trainEnd || 0) < AP.cfg.trainEvery * 60e3 || cs.length < 2 || !pk) return false;
      const st0 = JSON.parse(ev('JSON.stringify((QUEST_B.cur()||{}).st||null)') || 'null') || {}, ty = st0.type;
      if (ev('MAP.kind') === 'dungeon' || !(!ty || ty === 'level' || st0.need > (ev('PLAYER.level') || 0) || ev('(()=>{const c=QUEST_B.cur();return !!c&&!!c.b&&c.b.level>PLAYER.level&&c.i===0})()'))) return false;
      T = AP.k2.train = { id: pk.id, n: pk.n, until: now + AP.cfg.trainMin * 60e3 }; AP.k2.trainCamp = null; L('luyện tướng ' + T.n + ' ' + pk.lv + ' (' + AP.cfg.trainMin + '′)');
    }
    const t = cs.find(c => c.id === T.id);
    // đổi tướng yếu ra trận CHỈ khi đã ở map hợp cấp — đi ngang map 40–50 với Saphra 27 ra trận = gục giữa đường (27/10, 3 lượt liền)
    const sm = AP.sideMap && AP.sideMap(t.lv), m = pickMap(t.lv), there = (sm && ev('MAP_ID') === sm.id) || (m && ev('MAP_ID') === m.id);
    if (there && ev('active') !== T.id) { SWAP(T.n); await new Promise(r => setTimeout(r, 1500)); }
    if (sm && await AP.sideWork(sm.id)) { AP.state = 'luyện ' + T.n + ' ' + t.lv + ' · ' + AP.state; return true; } // ưu tiên nhiệm vụ phụ hợp cấp
    if (!m) { AP.k2.train = null; AP.k2.trainEnd = now; return false; }
    if ((ev('MAP_ID') || '') !== m.id) { if (now - (AP.k2.trainGoT || 0) > 90e3) { await AP.portalOk(); AP.k2.trainGoT = now; AP.k2.trainCamp = null; await G('auto off', 'go ' + MAPNAME(m.id)); L('luyện: tới ' + m.id); } AP.state = 'luyện ' + T.n + ' ' + t.lv + ' → ' + m.id; return true; }
    if (!AP.k2.trainCamp) {
      const zs = JSON.parse(ev(`JSON.stringify((MAP.zones||[]).map(z=>({lv:z.level,cs:z.camps.map(c=>({x:Math.round(c.x/10),y:Math.round(c.y/10)}))})))`) || '[]');
      const z = zs.filter(z => z.lv[1] <= t.lv).pop() || zs[0]; if (!z) return false; // ≤ cấp tướng (trước +2: Saphra Xạ Thủ 27 ở khu 25-28 gục mỗi lượt, 27/10)
      const c = z.cs.find(c => !ev(`mobs.some(m=>!m.dead&&m.level>=${t.lv + 5}&&Math.hypot(m.x/10-${c.x},m.y/10-${c.y})<35)`)) || z.cs[0];
      AP.k2.trainCamp = c; await G('go ' + c.x + ',' + c.y, 'wait arrived 20', 'auto on'); L('luyện ' + T.n + ' tại ' + m.id + ' ' + c.x + ',' + c.y + ' (khu ' + z.lv.join('-') + ')');
    } else if (!ev('AUTO.on')) { const c = AP.k2.trainCamp; await G('go ' + c.x + ',' + c.y, 'wait arrived 20', 'auto on'); }
    AP.state = 'luyện ' + T.n + ' ' + t.lv + ' @' + m.id + ' (còn ' + Math.round((T.until - now) / 60e3) + '′)'; return true;
  }
})();

// ---- nhiệm vụ phụ theo map (NPC hunter/scout/daredevil): trả khi đủ; nhận + làm khi cày cấp / luyện tướng ----
(() => {
  const ev = s => { try { return frames[0].eval(s); } catch (e) { return undefined; } };
  const L = m => { AP.log.push(new Date().toTimeString().slice(0, 5) + ' ' + m); if (AP.log.length > 80) AP.log.shift(); };
  const S = () => frames[0].QUEST_B.state(), mp = () => ev('MAP_ID') || '';
  AP.k2.noSide = AP.k2.noSide || {};
  AP.portalOk = async () => { const l = await G('look'); const b = l.match(/Leave [^\n]*\?[\s\S]*?\[(e\d+)\] Go\b/) || l.match(/\[(e\d+)\] Understood — enter/); if (b) { await G('click ' + b[1]); L('cổng: Go'); } }; // hộp hỏi rời map chặn tự đi; + Gatekeeper luật PK lần đầu vào map vàng/đỏ
  const fields = () => JSON.parse(ev(`JSON.stringify(Object.entries(MANIFEST.maps).filter(([k,m])=>m.kind==='field'&&m.level&&k[0]!=='_'&&(m.color==='green'||m.color==='yellow')).map(([k,m])=>({id:k,lv:m.level})))`) || '[]');
  const ready = () => { const s = S(); return Object.keys(s.side).filter(m => s.side[m] === 'got' && s.sideP[m] && s.sideP[m].step >= 2 && !AP.k2.noSide[m]); };
  AP.sideMap = lv => { const s = S(); const ms = fields().filter(m => s.side[m.id] !== 'done' && !AP.k2.noSide[m.id] && m.lv[0] <= Math.min(lv + 1, ev('PLAYER.level') || lv) && m.lv[1] >= lv - 4); ms.sort((a, b) => (s.side[b.id] === 'got') - (s.side[a.id] === 'got') || a.lv[0] - b.lv[0]); return ms[0]; };
  AP.sideWork = async m => { // true = đang lo việc ở map m
    if (mp() !== m) { if (Date.now() - (AP.k2.sideGoT || 0) > 90e3) { await AP.portalOk(); AP.k2.sideGoT = Date.now(); AP.k2.sideCamp = null; await G('auto off', 'go ' + MAPNAME(m)); L('phụ: tới ' + m); } AP.state = 'phụ → ' + m; return true; }
    const s = S(), st = s.side[m], p = s.sideP[m];
    if (st === 'got' && p && p.step >= 2) { const r = await SIDE_TURN(); L('phụ ' + m + ': trả · ' + String(r).slice(0, 60)); if (S().side[m] !== 'done') AP.k2.noSide[m] = 1; AP.k2.sideCamp = null; return true; } // step 0 đánh n quái → 1 nhặt k vật phẩm → 2 trả
    if (st === 'done') return false;
    if (!st || AP.k2.sideCamp !== m || !ev('AUTO.on')) { const r = String(await SIDE_GO()); if (/không có NPC|không thấy/.test(r) || !S().side[m]) { AP.k2.noSide[m] = 1; L('phụ ' + m + ': bỏ (' + r.slice(0, 50) + ')'); return false; } AP.k2.sideCamp = m; L('phụ ' + r.slice(0, 80)); }
    AP.state = 'phụ ' + SIDE_ST().slice(0, 60); return true;
  };
  const baseExt = AP.ext;
  AP.ext = async () => {
    if (baseExt && await baseExt()) return true; // việc ở thành + luyện tướng
    if (ev('MAP.kind') === 'dungeon') return false;
    const ty = ev('(QUEST_B.cur()||{}).st&&QUEST_B.cur().st.type') || '', idle = ty === 'level' || !ty || (ty === 'dungeon' && Date.now() < (AP.k2.dgBlocked || 0));
    const r = ready(); if (r.includes(mp()) || (idle && r.length)) return await AP.sideWork(r.includes(mp()) ? mp() : r[0]);
    const cs = JSON.parse(ev(`JSON.stringify(carry.filter(c=>c&&!champState(c).down).map(c=>({id:c,n:CHS[c].name,lv:lvlOf(c)})))`) || '[]').sort((a, b) => b.lv - a.lv);
    const top = cs[0]; if (!top) return false;
    if (!idle) { // đang làm nhiệm vụ chính: map đang đứng có phụ hợp cấp → nhận + làm xong rồi đi tiếp (như người chơi thật)
      const here = mp(), hm = fields().find(x => x.id === here), s = S();
