  const L = m => { AP.log.push(new Date().toTimeString().slice(0, 5) + ' ' + m); if (AP.log.length > 80) AP.log.shift(); };
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const FD = () => (AP.k2.fruitDone = AP.k2.fruitDone || {});
  function events() {
    const now = ev('ECO.now()') || Date.now(), top = ev('Math.max(...carry.filter(Boolean).map(lvlOf))') || 1;
    // CHAT_T.LOG nằm trong iframe → mất khi đổi map: gom tin vào AP.k2 (trang ngoài, không tải lại)
    const fresh = JSON.parse(ev(`JSON.stringify(CHAT_T.LOG.filter(m=>m.ch==='sys'&&/Cây Linh Quang kết trái ở/.test(m.text||'')).slice(-12).map(m=>[m.text,m.at]))`) || '[]');
    const ms = AP.k2.fruitMsgs = AP.k2.fruitMsgs || []; for (const x of fresh) if (!ms.some(y => y[1] === x[1])) ms.push(x); while (ms.length > 20) ms.shift();
    return ms.map(([t, at]) => {
      const m = /kết trái ở (.+?) kênh (\d+) — còn (\d+) phút/.exec(t); if (!m) return null;
      const mp = JSON.parse(ev(`JSON.stringify((Object.entries(MANIFEST.maps).find(([k,m])=>m.name===${JSON.stringify(m[1])})||[]).slice(0,2))`) || '[]');
      if (!mp[0] || !mp[1] || !/green|yellow/.test(mp[1].color) || (mp[1].level || [0, 0])[1] > top + 5) return null;
      return { map: mp[0], ch: +m[2], until: at + m[3] * 60e3, key: mp[0] + ':' + m[2] + ':' + at };
    }).filter(e => e && e.until - now > 60e3 && !FD()[e.key]);
  }
  const day = () => new Date().toDateString(), logEaten = () => ev(`CHAT_T.LOG.filter(m=>m.ch==='sys'&&/^Bạn ăn Quả/.test(m.text||'')).length`) || 0;
  const eaten = () => { const q = JSON.parse(ev('JSON.stringify(((ECO.eco()||{}).prog||{}).lq||null)') || 'null'); if (q && q.p === ev('ECO.day()')) return q.n || 0; const a = AP.k2.fruitAte; return a && a.day === day() ? a.n : 0; }; // máy chủ: prog.lq {p ngày, n quả} — bền qua tải lại trang
