    const ty = ev('(QUEST_B.cur()||{}).st&&QUEST_B.cur().st.type'); if (ty === 'dungeon' || ty === 'cut') return false;
    const E = events(); const e = E.find(x => x.map === (ev('MAP_ID') || '')) || E[0]; if (!e) return false;
    if ((ev('MAP_ID') || '') !== e.map) { if (Date.now() - (AP.k2.fruitGoT || 0) > 60e3) { AP.k2.fruitGoT = Date.now(); await AP.portalOk(); await G('auto off', 'go ' + MAPNAME(e.map)); L('quả Linh Quang: tới ' + e.map + ' kênh ' + e.ch); } AP.state = 'quả → ' + e.map; return true; }
    if (ev('NET.ch') !== e.ch) { ev(`NET.move(${e.ch})`); L('đổi kênh ' + e.ch); await sleep(5000); return true; }
    const B = JSON.parse(ev(`JSON.stringify((SKYFRUIT.list()||[]).filter(b=>b.left>0).map(b=>({id:b.id,d:Math.hypot(b.x-hero.x,b.y-hero.y),rare:b.rare})).sort((a,b)=>a.d-b.d))`) || '[]');
    if (!B.length) { if (Date.now() > e.until || (AP.k2.fruitEmpty = (AP.k2.fruitEmpty || 0) + 1) > 40) { FD()[e.key] = 1; AP.k2.fruitEmpty = 0; L('quả ' + e.map + ': hết'); return false; } AP.state = 'chờ quả chín ' + e.map; return true; }
    AP.k2.fruitEmpty = 0; const n0 = logEaten();
