    else if (/interrupted|ngắt/.test(ev(`[...document.querySelectorAll('.toast,#toast,.ftxt')].slice(-2).map(e=>e.textContent).join(' ')`) || '')) { await G('auto on'); await sleep(6000); await G('auto off'); }
