// ---- thám hiểm (Trưởng Đoàn Thám Hiểm, từ cấp 30; 3 việc/ngày × 8 h): về thành nhận thưởng → đưa tướng rảnh lại vào carry → giao việc mới (khớp gợi ý ×1,5) ----
(() => {
  const ev = s => { try { return frames[0].eval(s); } catch (e) { return undefined; } };
  const L = m => { AP.log.push(new Date().toTimeString().slice(0, 5) + ' ' + m); if (AP.log.length > 80) AP.log.shift(); };
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const W = () => frames[0];
  function plan() { // {claim:[run id], send:[{task, champ}], fill:bool}
    const w = W(); if (!w.EXPED || ev('PLAYER.level') < w.EXPED.C.LEVEL) return null;
    const S = w.EXPED.state(), now = ev('ECO.on()') ? ev('ECO.now()') : Date.now();
    const claim = S.runs.filter(r => r.end <= now).map(r => r.id);
    const free = ev(`JSON.stringify(OWNED.map(o=>o.id).filter(id=>CHS[id]&&id!==active&&!EXPED.busy(id)))`);
    const fr = JSON.parse(free || '[]').filter(id => !claim.some(c => S.runs.find(r => r.id === c && r.champ === id)));
    const left = Math.max(0, w.EXPED.C.MAX_OPEN - (S.runs.length - claim.length));
    const jobs = w.EXPED.jobs().filter(t => !S.taken.includes(t.id) && !w.EXPED.why.task(t).replace('Chỉ giao việc ở thành, thị trấn', ''));
    const pool = fr.concat(claim.map(c => S.runs.find(r => r.id === c).champ)), send = [];
    for (const t of jobs.slice(0, left)) {
      const lv = id => ev(`lvlOf(${JSON.stringify(id)})`) || 0, hit = id => ev(`CHS[${JSON.stringify(id)}][${JSON.stringify(t.hint.kind)}]===${JSON.stringify(t.hint.v)}`);
      const cs = pool.filter(id => !send.some(s => s.champ === id)).sort((a, b) => hit(b) - hit(a) || lv(a) - lv(b));
      if (cs[0]) send.push({ task: t.id, champ: cs[0], hit: hit(cs[0]) });
    }
    const empty = ev('carry.filter(Boolean).length') < 3 && pool.some(id => !send.some(s => s.champ === id) && !ev(`carry.includes(${JSON.stringify(id)})`));
    return (claim.length || send.length || empty) ? { claim, send, fill: empty } : null;
  }
  async function exped() {
    if (Date.now() - (AP.k2.expT || 0) < 10 * 60e3 || ev('MAP.kind') === 'dungeon') return false;
    const ty = ev('(QUEST_B.cur()||{}).st&&QUEST_B.cur().st.type'); if (ty === 'cut') return false;
    const p = plan(); if (!p) { AP.k2.expT = Date.now(); return false; }
    if (!ev('inTown()')) { // chỉ về thành khi có thưởng chờ hoặc còn lượt giao việc
      if (!p.claim.length && !p.send.length) { AP.k2.expT = Date.now(); return false; }
      if (Date.now() - (AP.k2.expGoT || 0) > 120e3) { AP.k2.expGoT = Date.now(); await AP.portalOk(); await G('auto off', 'go ' + MAPNAME('elmbrook')); L('về thành: thám hiểm (' + p.claim.length + ' nhận, ' + p.send.length + ' giao)'); }
