    for (const s of p.send) { const r = await W().EXPED.send(s.task, s.champ); L('thám hiểm giao ' + s.champ + (s.hit ? ' (khớp)' : '') + ': ' + String(r && (r.msg || r.ok)).slice(0, 60)); await sleep(800); }
    const want = JSON.parse(ev(`JSON.stringify(OWNED.map(o=>o.id).filter(id=>CHS[id]&&!EXPED.busy(id)).sort((a,b)=>(b===active)-(a===active)||lvlOf(b)-lvlOf(a)).slice(0,3))`) || '[]');
    const cur = JSON.parse(ev('JSON.stringify(carry)') || '[]');
    if (want.length && (cur.filter(Boolean).length < Math.min(3, want.length) || want.some(id => !cur.includes(id)))) {
      const next = [ev('active'), ...want.filter(id => id !== ev('active'))].slice(0, 3); while (next.length < 3) next.push(null);
      await W().carryEdit(next); await sleep(1000); L('carry → ' + ev('JSON.stringify(carry)'));
    }
    AP.k2.expT = Date.now(); AP.k.gearT = 0; AP.k.fight = null; return true;
  }
  const baseExt = AP.ext;
  AP.ext = async () => (await exped()) || !!(baseExt && await baseExt());
})();

// ---- nghề trên đường (6 nghề đã học 2026-10-26): map luyện công → hái bụi thảo dược / quả dại trong 25 ô (1 Sức Nghề/lần, 3 s) + ăn món No Bụng (Nướng/Hầm/…) khi ô trống ----
(() => {
  const ev = s => { try { return frames[0].eval(s); } catch (e) { return undefined; } };
