  const sleep = ms => new Promise(r => setTimeout(r, ms));
  AP.k2.herbBad = AP.k2.herbBad || {};
  async function eat() {
    if (Date.now() - (AP.k2.eatT || 0) < 5 * 60e3) return; AP.k2.eatT = Date.now();
    const need = JSON.parse(ev(`JSON.stringify((()=>{const f=((ECO.eco()||{}).ent||{}).foods||[];const have=new Set(f.filter(x=>x.sec>300).map(x=>x.k));return bag.filter(b=>b&&b.act==='food'&&b.food&&!have.has(b.food.k||'')).map(b=>b.name)})())`) || '[]');
    const seen = new Set(); for (const n of need) { const k = ev(`(bag.find(b=>b&&b.name===${JSON.stringify(n)})||{}).food.k`); if (seen.has(k)) continue; seen.add(k); await G('use ' + n); L('ăn ' + n); await sleep(1200); }
  }
  async function herb() { try { return await herb1(); } catch (e) { return false; } } // đổi map giữa lúc hái → frame cũ mất HERB
  async function herb1() {
