    const tier = Math.floor(((ev('ECO.eco().job.herb.lv') || 1) - 1) / 10) + 1; // bụi bậc t = bậc map; nghề bậc thấp hơn → khoá (35 lần hái hụt ở map 4x khi Hái Thuốc bậc 1)
    const b = (w.HERB.list() || []).filter(b => !b.busy && !AP.k2.herbBad[b.id] && (b.t || 1) <= tier && Math.hypot(b.x - hx, b.y - hy) < 250).sort((a, c) => Math.hypot(a.x - hx, a.y - hy) - Math.hypot(c.x - hx, c.y - hy))[0];
    if (!b) return false;
    if (ev(`mobs.some(m=>!m.dead&&m.hp>0&&m.state==='fight'&&Math.hypot(m.x-hero.x,m.y-hero.y)<320)`)) return false; // quái đang giao chiến gần: để Auto dọn trước, hái sau (bị đánh trúng là ngắt)
    const auto = ev('AUTO.on'); if (auto) await G('auto off');
