    t0 = Date.now(); while (w.HERB.busy() && Date.now() - t0 < 9000) await sleep(200);
    const n1 = ev('bag.reduce((a,x)=>a+(x&&x.job?x.count||1:0),0)');
    const fought = ev(`mobs.some(m=>!m.dead&&m.hp>0&&m.state==='fight'&&Math.hypot(m.x-hero.x,m.y-hero.y)<320)`);
    if (n1 > n0) L('hái ' + (b.k === 'f' ? 'quả dại' : b.k === 'r' ? 'thảo dược HIẾM' : 'thảo dược') + ' +' + (n1 - n0)); else if (!fought) AP.k2.herbBad[b.id] = 1; // bị quái ngắt thì không bỏ bụi
    if (auto) await G('auto on');
