// ---- Bí Cảnh (khe mọc ngẫu nhiên trên map luyện công, 3 lượt/ngày dồn): bọc bcNet.bcr (khe {id,x,y,close,end} | {id,off}) + bcNet.bcc (rương {rid,f,k,x,y}) để biết toạ độ ·
//      ngoài: còn lượt + khe đóng sau > 90 s → tới khe → "Xem khe" → "Vào 1 mình" · trong (MAP.mode 'bicanh'): Auto dọn → trận Lên → boss → MỞ RƯƠNG (≤ 80 px, F) → trận Thoát ----
(() => {
  const ev = s => { try { return frames[0].eval(s); } catch (e) { return undefined; } };
  const L = m => { AP.log.push(new Date().toTimeString().slice(0, 5) + ' ' + m); if (AP.log.length > 80) AP.log.shift(); };
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  const K = () => (AP.k2.bc = AP.k2.bc || { rifts: {}, chest: null, opened: {} });
  const panelBtn = (l, re) => { const m = (l.split('Open panels:')[1] || '').match(re); return m ? m[1] : null; };
  function hook() {
    const w = frames[0]; if (!w || !w.bcNet || w.bcNet.__ap) return;
    const r0 = w.bcNet.bcr, c0 = w.bcNet.bcc, mp = w.eval('MAP_ID'); // MAP_ID là let trong iframe — không phải thuộc tính window
    w.bcNet.bcr = m => { try { const R = K().rifts; if (m.off) delete R[m.id]; else R[m.id] = { id: m.id, x: m.x, y: m.y, close: m.close, end: m.end, map: mp }; } catch (e) {} return r0(m); };
    w.bcNet.bcc = m => { try { K().chest = { rid: m.rid, f: m.f, x: m.x, y: m.y }; } catch (e) {} return c0(m); };
    w.bcNet.__ap = 1;
  }
  async function inside() {
    const s = frames[0].BICANH.state(), B = s.B; if (!B) return true;
    const gs = B.gates || [], up = gs.find(g => g.k === 'up'), ex = gs.find(g => g.k === 'exit');
    if (B.f !== K().lastF) { K().lastF = B.f; L('Bí Cảnh tầng ' + B.f + ' · ' + B.left + ' quái'); }
    if (up && B.left === 0) { await G('auto off', 'go ' + Math.round(up.x / 10) + ',' + Math.round(up.y / 10), 'wait arrived 15'); AP.state = 'Bí Cảnh: lên tầng'; return true; }
    if (ex) {
      const c = K().chest, key = c && c.rid + ':' + c.f;
      if (c && !K().opened[key]) {
        await G('auto off', 'go ' + Math.round(c.x / 10) + ',' + Math.round(c.y / 10), 'wait arrived 15'); await sleep(1500);
        const l = String(await G('look')), b = panelBtn(l, /\[(e\d+)\] (Mở rương|Open chest|Open)[^\n]*/);
        if (b) { await G('click ' + b); await sleep(2500); K().opened[key] = 1; L('Bí Cảnh: mở rương ' + String(await G('look')).split('Open panels:')[1]?.replace(/\s+/g, ' ').slice(0, 140)); for (let i = 0; i < 2; i++) await G('close'); }
        else if ((K().chestTry = (K().chestTry || 0) + 1) > 4) { K().opened[key] = 1; L('Bí Cảnh: không thấy nút mở rương'); }
        AP.state = 'Bí Cảnh: mở rương'; return true;
      }
      await G('auto off', 'go ' + Math.round(ex.x / 10) + ',' + Math.round(ex.y / 10), 'wait arrived 15'); await sleep(3000);
      const l = String(await G('look')), b = panelBtn(l, /\[(e\d+)\] (Back to the rift|Về chỗ khe)/); if (b) await G('click ' + b);
      L('Bí Cảnh: thoát'); K().chest = null; K().chestTry = 0; AP.state = 'Bí Cảnh: thoát'; return true;
    }
    const far = JSON.parse(ev(`JSON.stringify((()=>{const a=mobs.filter(m=>!m.dead&&m.hp>0).map(m=>({x:m.x,y:m.y,d:Math.hypot(m.x-hero.x,m.y-hero.y)})).sort((p,q)=>p.d-q.d);return a[0]&&a[0].d>240?a[0]:null})())`) || 'null');
    if (B.left > 0 && far) { await G('auto off', 'go ' + Math.round(far.x / 10) + ',' + Math.round(far.y / 10), 'wait arrived 15', 'auto on'); AP.state = 'Bí Cảnh: tới quái xa'; return true; } // quái ngoài vòng Auto → tầng không xong (kẹt 23′ ở tầng 1)
    if (!ev('AUTO.on')) await G('auto on');
    AP.state = 'Bí Cảnh tầng ' + B.f + ' (' + B.left + ' quái' + (s.BB ? ', boss ' + Math.round(100 * s.BB.hp / s.BB.max) + '%' : '') + ')'; return true;
  }
  async function bicanh() {
    hook();
    if (ev('MAP.mode') === 'bicanh') return await inside();
    if (ev('MAP.kind') !== 'field' || !frames[0].BICANH) return false;
    const ty = ev('(QUEST_B.cur()||{}).st&&QUEST_B.cur().st.type'); if (ty === 'cut' || ty === 'dungeon') return false;
    if ((frames[0].BICANH.state().turns || 0) <= 0) return false;
    const mlv = JSON.parse(ev('JSON.stringify(MAP.level||null)') || 'null'); if (!mlv || mlv[1] < (ev('PLAYER.level') || 1) - 5) return false; // map thấp quá → "Empty chest — level gap too large" (Rừng Sương 21–30 khi cấp 47)
    const now = ev('ECO.now()') || Date.now(), here = ev('MAP_ID');
    const r = Object.values(K().rifts).find(r => r.map === here && r.close - now > 90e3); if (!r) return false;
    if (!K().seen || K().seen !== r.id) { K().seen = r.id; L('thấy khe Bí Cảnh ở ' + here + ' ' + Math.round(r.x / 10) + ',' + Math.round(r.y / 10)); }
    await G('auto off', 'go ' + Math.round(r.x / 10) + ',' + Math.round(r.y / 10), 'wait arrived 20'); await sleep(1500);
    let l = String(await G('look')); const v = panelBtn(l, /\[(e\d+)\] (Xem khe|View rift|View the rift|Inspect)[^\n]*/);
    if (v) { await G('click ' + v); await sleep(1500); l = String(await G('look')); }
    const s = panelBtn(l, /\[(e\d+)\] (Vào 1 mình|Go solo|Enter solo|Solo)[^\n]*/);
    if (s) { await G('click ' + s); L('vào Bí Cảnh 1 mình'); K().lastF = 0; await sleep(8000); }
    else { L('khe: không thấy nút vào · ' + (l.split('Open panels:')[1] || '').replace(/\s+/g, ' ').slice(0, 160)); delete K().rifts[r.id]; }
    return true;
  }
  const baseExt = AP.ext;
