// dungeon: 1 lượt cùng bot ở phó bản hợp cấp — chỉ khi bước chính đang là cày cấp (để dành lượt cho phó bản truyện) · xong → trả việc + mở rương mốc 25/50/75/100.
(() => {
  const ev = s => { try { return frames[0].eval(s); } catch (e) { return undefined; } };
