  const DS = () => JSON.parse(ev('JSON.stringify(dailyState())') || 'null');
  const inTownWith = id => ev('MAP.kind') === 'town' && !!ev(`npcs.some(n=>n.id===${JSON.stringify(id)})`);
  const homeTown = () => ((ev('PLAYER.level') || 1) >= 40 ? 'aurelion' : 'elmbrook');
  async function toTown(why) {
    if (Date.now() - (AP.k2.dyGoT || 0) > 120e3) { AP.k2.dyGoT = Date.now(); await AP.portalOk(); await G('auto off', 'go ' + MAPNAME(homeTown())); L('việc ngày: về thành (' + why + ')'); }
    AP.state = 'việc ngày → thành (' + why + ')'; return true;
  }
  async function enhance() { // Thợ rèn: "Enhance slot" → chọn tướng chính (cường hoá giữ ở Ô của tướng) → ô Vũ khí mặc định → nút "Enhance" cuối bảng (100% tới +n thấp; 15·2^k HT + 500·2^k vàng)
    await AP.talkId('smith'); await sleep(1500);
    let P = (String(await G('look')).split('Open panels:')[1] || ''); const t = P.match(/\[(e\d+)\] Enhance slot/);
    if (t) { await G('click ' + t[1]); await sleep(1500); P = (String(await G('look')).split('Open panels:')[1] || ''); }
    const top = ev(`CHS[Object.keys(EQUIP).sort((a,b)=>lvlOf(b)-lvlOf(a))[0]].name`) || 'Brokk', c = P.match(new RegExp('\\[(e\\d+)\\] ' + top + ' ·'));
    if (c) { await G('click ' + c[1]); await sleep(1200); P = (String(await G('look')).split('Open panels:')[1] || ''); }
    const b = [...P.matchAll(/\[(e\d+)\] Enhance(?! slot| ⊘)[^\n]*/g)].pop();
    if (b) { await G('click ' + b[1]); await sleep(1500); L('việc ngày: cường hoá ' + top + ' · ' + ((String(await G('look')).match(/Enhancement successful[^\n]*/) || ['?'])[0])); }
    else L('việc ngày: không thấy nút cường hoá · ' + P.replace(/\s+/g, ' ').slice(0, 200));
    for (let i = 0; i < 4; i++) { const r = await G('close'); if (/No panel/.test(r)) break; }
  }
  const pickDungeon = () => JSON.parse(ev(`JSON.stringify((()=>{const L=PLAYER.level;const ds=Object.entries(MANIFEST.maps).filter(([k,m])=>m.kind==='dungeon'&&m.level&&m.level[0]<=L&&k[0]!=='_').sort((a,b)=>b[1].level[0]-a[1].level[0]);return ds[0]?ds[0][0]:null})())`) || 'null');
