    const ty = ev('(QUEST_B.cur()||{}).st&&QUEST_B.cur().st.type') || ''; if (ty === 'cut') return false;
    if (AP.k2.dyDone === d.day) return false;
    const T = d.tasks, ready = T.some(t => t.st === 'new' || (t.st === 'on' && t.got >= t.n));
    if (ready && Date.now() - (AP.k2.dyClerkT || 0) > 3 * 60e3) {
      if (!inTownWith('guild_clerk')) return await toTown('nhận/trả việc');
      AP.k2.dyClerkT = Date.now(); AP.k2.dailyDay = null; await AP.daily();
