    const tw = (k, f, gap) => { const key = 'dy_' + k; if (Date.now() - (AP.k2[key] || 0) < gap) return null; return async () => { if (!inTownWith('smith') && k !== 'buy') return await toTown(k); if (k === 'buy' && !inTownWith('alchemist')) return await toTown(k); AP.k2[key] = Date.now(); await f(); return true; }; };
    if (on('buy')) { const f = tw('buy', () => AP.buyPots(AP.potN() + 10), 15 * 60e3); if (f) return await f(); }
    if (on('salvage')) { const f = tw('salvage', () => AP.salvage(), 20 * 60e3); if (f) return await f(); }
