    const ty = ev('(QUEST_B.cur()||{}).st&&QUEST_B.cur().st.type') || '', need = ev('((QUEST_B.cur()||{}).st||{}).need') || 0;
    if (ty !== 'level' && !(need > (ev('PLAYER.level') || 0))) return false; // cày cấp, kể cả bước chờ cấp (st.need)
    const l0 = String(await G('look')), inv = pick(l0, /\[(e\d+)\] Join party/); if (inv) { await G('click ' + inv); L('tổ đội: nhận lời mời'); await sleep(2000); }
    const P = JSON.parse(ev(`JSON.stringify({id:PARTY.id,lead:PARTY.leader,ms:(PARTY.members||[]).map(m=>({id:m.id,me:!!m.me,name:m.name||'',map:m.map,x:m.x,y:m.y}))})`) || '{}'), here = ev('MAP_ID');
    if (P.id && (P.ms || []).length > 1) {
      const hx = ev('hero.x'), hy = ev('hero.y'), others = P.ms.filter(m => !m.me), near = others.filter(m => m.map === here && Math.hypot(m.x - hx, m.y - hy) < 1067);
      if (AP.k2.ptId !== P.id) { AP.k2.ptId = P.id; AP.k2.ptNearT = Date.now(); L('tổ đội: vào đội ' + others.map(m => m.name).join(', ')); }
      if (near.length) AP.k2.ptNearT = Date.now();
      else if (Date.now() - (AP.k2.ptNearT || 0) > 10 * 60e3) { await G('open party'); await sleep(1500); const lv = pick(String(await G('look')), /\[(e\d+)\] Leave party/); if (lv) await G('click ' + lv); await closeAll(); L('tổ đội: 10′ không ai trong tầm → rời đội'); AP.k2.ptId = null; return false; }
      const ld = P.ms.find(m => m.id === P.lead);
      if (!ld || ld.me || ld.map !== here) return false;              // mình là đội trưởng / đội trưởng ở map khác: cày như thường (AP tự chọn bãi)
      if (Math.hypot(ld.x - hx, ld.y - hy) > 450) await G('auto off', 'go ' + Math.round(ld.x / 10) + ',' + Math.round(ld.y / 10), 'wait arrived 20');
      if (!ev('AUTO.on')) await G('auto on');
      AP.state = 'cày cùng tổ đội (' + ld.name + ', ' + P.ms.length + ' người)'; return true;
    }
    if (Date.now() - (AP.k2.ptT || 0) < 3 * 60e3) return false;
    AP.k2.ptT = Date.now();
    await G('open party'); await sleep(2000); let l = String(await G('look'));
    const ap = pick(l, /\[(e\d+)\] Apply[^\n⊘·]*Hunter[^\n⊘·]*(?=\s|·|$)/) || pick(l, /\[(e\d+)\] Apply(?![^\n·]*⊘)/);
    if (ap) { await G('click ' + ap); L('tổ đội: xin vào đội gần đây'); await sleep(1500); l = String(await G('look')); }
    const fd = pick(l, /\[(e\d+)\] Find grinding party(?! ⊘)/); if (fd && !/Cancel search/.test(l)) { await G('click ' + fd); L('tổ đội: bật Tìm đội cày'); }
    await closeAll(); return false;
  }
  const baseExt = AP.ext;
  AP.ext = async () => { if (baseExt && await baseExt()) return true; try { return await party(); } catch (e) { L('tổ đội lỗi ' + e.message); return false; } };
})();

// ---- TIN TỨC (người dùng dặn 2026-10-27: mục News cập nhật liên tục, nhớ kiểm tra): 10′/lần đọc NOTICE.news() → bài mới (id > k2.newsSeen) ghi "TIN MỚI #id: tiêu đề"
//      vào log để Claude thấy trong AP.report và đọc nội dung (NOTICE.news() phần tử {id, at, title, body}). Không bao giờ giữ quyền điều khiển.
