// ---- CƯỜNG HOÁ ĐỀU (người dùng dặn 2026-10-27 "nâng đều hết"): ghé thành có Thợ rèn + vàng ≥ 50k + giá mức kế của ô thấp nhất → ENHALL(5, 50000) (tools/jobs.js) nền.
//      Trần +5 (từ +6 hỏng là tụt cấp). Không đi riêng về thành vì việc này; 1 lần / 30′. 27/10: mọi ô +4 (Nhẫn 1 +5, Ngọc bội +3).
(() => {
  const ev = s => { try { return frames[0].eval(s); } catch (e) { return undefined; } };
