    const id = ev(`Object.keys(EQUIP).filter(c=>carry.includes(c)).sort((a,b)=>lvlOf(b)-lvlOf(a))[0]`);
    const plus = JSON.parse(ev(`JSON.stringify((ECO.eco().plus||{})['${id}']||{})`) || '{}'), lo = Math.min(...['weapon', 'helm', 'armor', 'gloves', 'belt', 'boots', 'neck', 'ring1', 'ring2', 'jade'].map(s => plus[s] || 0));
    if (lo >= 5) return false;
