    AP.k2.enhT = Date.now(); AP.k2.enhRun = true; L('cường hoá đều: ô thấp nhất +' + lo + ' → ENHALL(5, 50000)'); ENHALL(5, 50000); return true;
  }
  const baseExt = AP.ext;
  AP.ext = async () => { try { if (await enh()) return true; } catch (e) { L('cường hoá lỗi ' + e.message); } return !!(baseExt && await baseExt()); };
})();

// ---- CẤT ĐỒ TÍM+ VÀO KHO (người dùng dặn 2026-10-28: đồ Tím trở lên để dành cho tướng cấp thấp dùng sau). Kho = "Account storage", CHUNG mọi tướng của tài khoản
//      (KHÔNG sang tài khoản khác; đồ nhặt đều khoá → cũng không qua Chợ). Ghé thành có Người Giữ Kho `keeper` → "Storage · page…" → chuột phải món túi (sự kiện
//      contextmenu — lệnh AI không có chuột phải; cửa sổ Kho che cột đầu Túi nên chuột thật không tới) → món sang Kho. Chỉ món tướng chính đã mặc được mà GEARDO
//      không chọn (itemReq ≤ cấp cao nhất trong carry); món cần cấp cao hơn giữ trong túi cho tướng chính sau này. 1 lần / 20′.
(() => {
  const ev = s => { try { return frames[0].eval(s); } catch (e) { return undefined; } };
  const L = m => { AP.log.push(new Date().toTimeString().slice(0, 5) + ' ' + m); if (AP.log.length > 80) AP.log.shift(); };
  const sleep = ms => new Promise(r => setTimeout(r, ms));
  async function stash() {
    if (Date.now() - (AP.k2.stashT || 0) < 20 * 60e3) return false;
    if (!(ev('MAP.kind') === 'town' && ev(`npcs.some(n=>n.id==='keeper')`))) return false;
    // món Tím+ cần cấp > tướng chính = đồ tương lai của tướng chính → cả lượt bỏ (không phân biệt được ô nào trên giao diện)
    const s = JSON.parse(ev(`JSON.stringify((()=>{const mx=Math.max(...carry.filter(Boolean).map(lvlOf));const e=bag.filter(b=>b&&b.type==='equip'&&b.q>=3);return {n:e.length,fut:e.filter(b=>itemReq(b)>mx).length}})())`) || '{}');
    if (!s.n || s.fut) return false;
    AP.k2.stashT = Date.now();
    await AP.talkId('keeper'); await sleep(2000);
    let p = String(await G('look')).split('Open panels:')[1] || ''; const b = p.match(/\[(e\d+)\] Storage · page/); if (b) { await G('click ' + b[1]); await sleep(2000); }
    p = String(await G('look')).split('Open panels:')[1] || ''; const eq = p.match(/\[(e\d+)\] Equipment/); if (eq) { await G('click ' + eq[1]); await sleep(800); } // Túi chỉ hiện trang bị
    const W = frames[0];
    let n = 0;
    for (let i = 0; i < s.n; i++) {
      const cell = [...W.document.querySelectorAll('[aria-label]')].find(e => e.offsetParent && !e.closest('[class*=store],[id*=store]') && / — (Purple|Red)$/.test(e.getAttribute('aria-label')));
      if (!cell) break;
      const before = ev('bag.filter(Boolean).length'), r = cell.getBoundingClientRect();
      cell.dispatchEvent(new W.MouseEvent('contextmenu', { bubbles: true, cancelable: true, button: 2, clientX: r.x + 5, clientY: r.y + 5 })); await sleep(1300);
      if (ev('bag.filter(Boolean).length') >= before) break; n++;
    }
    for (let i = 0; i < 4; i++) { const r = await G('close'); if (/No panel/.test(r)) break; }
    L('cất kho: ' + n + ' món Tím+ (kho ' + ev('(PILOT.store.pages[0]||[]).filter(Boolean).length') + '/60)'); return n > 0;
  }
  const baseExt = AP.ext;
  AP.ext = async () => { try { if (await stash()) return true; } catch (e) { L('cất kho lỗi ' + e.message); } return !!(baseExt && await baseExt()); };
})();

// ---- VẠN QUÂN MỖI TRẬN (28/10): Chiến Trường Vạn Quân 13:00 · 21:00 giờ game (sảnh mở trước 10′, vào muộn tới :13) — ≥ 10 điểm là EXP tham gia mỗi phút
//      KHÔNG cần Giờ treo (28/10 01:00: +82.860 EXP ở cấp 53) → từ h−9′ tới h+11′: về Kinh đô → VQRUN() (tools/jobs.js) nền, giữ quyền tới khi xong. 1 lần / trận.
(() => {
  const ev = s => { try { return frames[0].eval(s); } catch (e) { return undefined; } };
  const L = m => { AP.log.push(new Date().toTimeString().slice(0, 5) + ' ' + m); if (AP.log.length > 80) AP.log.shift(); };
  const game = () => new Date(Date.now() + 7 * 3600e3);
  async function vq() {
    if (AP.k2.vqRun) {
      if (window.__vq && !__vq.done) { AP.state = 'Vạn Quân: ' + ((__vq.log.slice(-1)[0]) || '…'); return true; }
      AP.k2.vqRun = false; const lg = (window.__vq && __vq.log.slice(-2).join(' · ')) || 'xong'; L('Vạn Quân: ' + lg);
      if (/không vào được|chưa vào|cần đứng/.test(lg) && (AP.k2.vqTry = (AP.k2.vqTry || 0) + 1) < 3) AP.k2.vqKey = null; // sảnh chưa mở / lạc map → thử lại (tối đa 3)
      return false;
    }
    if (typeof VQRUN !== 'function') return false;
    const d = game(), m = d.getUTCHours() * 60 + d.getUTCMinutes(), slot = [13, 21].find(h => m >= h * 60 - 9 && m < h * 60 + 11);
    if (!slot) return false;
    const key = d.toISOString().slice(0, 10) + '@' + slot; if (AP.k2.vqKey === key) return false;
    if (AP.k2.vqSlot !== key) { AP.k2.vqSlot = key; AP.k2.vqTry = 0; }
    if (ev('(PILOT.inst||{}).kind') || ev('MAP.kind') === 'dungeon' || ev('MAP.mode') === 'bicanh') return false; // để Tháp/Đấu trường/phó bản xong trước
    if (ev('MAP_ID') !== 'aurelion' && ev('MAP_ID') !== 'songky') {
      if (Date.now() - (AP.k2.vqGoT || 0) > 90e3) { AP.k2.vqGoT = Date.now(); await AP.portalOk(); await G('auto off', 'go ' + MAPNAME('aurelion')); L('Vạn Quân ' + slot + ':00: tới Kinh đô'); }
      AP.state = 'Vạn Quân → Kinh đô'; return true;
    }
    if (Date.now() - (AP.k2.vqStartT || 0) < 60e3) { AP.state = 'Vạn Quân: chờ thử lại'; return true; }
    AP.k2.vqKey = key; AP.k2.vqRun = true; AP.k2.vqStartT = Date.now(); L('Vạn Quân ' + slot + ':00: VQRUN'); VQRUN(); return true;
  }
  const baseExt = AP.ext;
  AP.ext = async () => { try { if (await vq()) return true; } catch (e) { L('Vạn Quân lỗi ' + e.message); } return !!(baseExt && await baseExt()); };
})();

// ---- BÁ CHỦ (tin #34, 28/10): boss ngẫu nhiên 08:00–22:00 giờ game ở map luyện công (SETTINGS.sboss: sống 60′, vòng rx 440 ry 220 — đứng NGOÀI vòng boss miễn
//      sát thương), rương Bá Chủ ~4× vàng + 10 Tàn Hồn + món đầu luôn Tím, đồ theo cấp người nhận, 3 rương/ngày (đếm ở AP.k2.sbN — game không lộ bộ đếm).
//      SBOSS.live() = [{id, boss, map, ch, x, y, lv, end}] (nạp từ /api/net/sboss mỗi lần vào map + tin thức tỉnh) · SBOSS.go(t) dẫn đường + đổi kênh · SBOSS.ring().
//      Chọn boss lv ≤ cấp + 2 còn ≥ 6′, gần cấp mình nhất → tới → Auto trong vòng → boss chết/biến mất: +1 lượt (khối RƯƠNG nhặt rương). Gục 3 lần / quá 20′ → bỏ boss đó.
(() => {
  const ev = s => { try { return frames[0].eval(s); } catch (e) { return undefined; } };
  const L = m => { AP.log.push(new Date().toTimeString().slice(0, 5) + ' ' + m); if (AP.log.length > 80) AP.log.shift(); };
  const gday = () => new Date(Date.now() + 7 * 3600e3).toISOString().slice(0, 10);
  async function sb() {
    if (AP.k2.sbDay !== gday()) { AP.k2.sbDay = gday(); AP.k2.sbN = 0; AP.k2.sbSkip = {}; }
    if ((AP.k2.sbN || 0) >= 3 || !frames[0].SBOSS) return false;
    if (ev('(PILOT.inst||{}).kind') || ev('MAP.kind') === 'dungeon' || ev('MAP.mode') === 'bicanh' || window.__gobHunt || AP.k2.vqRun) return false;
    const gd = new Date(Date.now() + 7 * 3600e3), gm = gd.getUTCHours() * 60 + gd.getUTCMinutes();
    if ([13, 21].some(h => gm >= h * 60 - 9 && gm < h * 60 + 11)) return false; // nhường Vạn Quân (+80k EXP/trận)
    const lv = ev('PLAYER.level') || 1, now = ev('ECO.on()?ECO.now():Date.now()') || Date.now(), skip = AP.k2.sbSkip || (AP.k2.sbSkip = {});
    const live = JSON.parse(ev('JSON.stringify(SBOSS.live())') || '[]');
    let cur = AP.k2.sbCur && live.find(t => t.id === AP.k2.sbCur.id);
    if (AP.k2.sbCur && !cur) { // boss hết (bị hạ / hết giờ) → tính lượt nếu mình đã đánh
      if (AP.k2.sbCur.hit) { AP.k2.sbN = (AP.k2.sbN || 0) + 1; L('Bá Chủ ' + AP.k2.sbCur.boss + ' xong → lượt ' + AP.k2.sbN + '/3 (khối RƯƠNG nhặt rương)'); }
      AP.k2.sbCur = null;
    }
    if (!cur) {
      cur = live.filter(t => !skip[t.id] && (t.lv || 0) <= lv + 2 && (!t.end || t.end - now > 6 * 60e3)).sort((a, b) => Math.abs(lv - (a.lv || 0)) - Math.abs(lv - (b.lv || 0)))[0];
      if (!cur) return false;
      AP.k2.sbCur = { id: cur.id, boss: cur.boss, t0: Date.now(), dead: 0, hit: false }; L('Bá Chủ: ' + cur.boss + ' L' + cur.lv + ' ở ' + cur.map + ' kênh ' + cur.ch + ' → đi đánh');
    }
    const C = AP.k2.sbCur;
    if (Date.now() - C.t0 > 20 * 60e3 || C.dead >= 3) { skip[C.id] = 1; L('Bá Chủ: bỏ ' + C.boss + (C.dead >= 3 ? ' (gục 3 lần)' : ' (quá 20′)')); AP.k2.sbCur = null; await G('auto off'); return false; }
    if (ev('hero.dead')) { if (!C.wasDead) { C.wasDead = true; C.dead++; } AP.state = 'Bá Chủ: gục ' + C.dead + '/3 — chờ hồi'; return true; }
    C.wasDead = false;
    const ch = ev('typeof NET!=="undefined"&&NET?NET.ch:1');
    if (ev('MAP_ID') !== cur.map || ch !== cur.ch) {
      if (!ev('!!hero.goal') && Date.now() - (C.goT || 0) > 45e3) { C.goT = Date.now(); await AP.portalOk(); await G('auto off'); ev('SBOSS.go(SBOSS.live().find(t=>t.id===' + JSON.stringify(cur.id) + '))'); }
      AP.state = 'Bá Chủ → ' + cur.map + ' kênh ' + cur.ch; return true;
    }
    const r = JSON.parse(ev('JSON.stringify(SBOSS.ring())') || 'null'), hx = ev('hero.x'), hy = ev('hero.y');
    const boss = JSON.parse(ev('JSON.stringify((m=>m?{x:m.x,y:m.y,hp:Math.round(m.hp/m.maxHp*100)}:null)(mobs.find(m=>m.sp&&m.sp.sb&&!m.dead)))') || 'null');
    if (r && ((hx - r.x) / r.rx) ** 2 + ((hy - r.y) / r.ry) ** 2 > 0.6) { await G('auto off', 'go ' + Math.round((r.x + (hx - r.x) * 0.3) / 10) + ',' + Math.round((r.y + (hy - r.y) * 0.3) / 10)); AP.state = 'Bá Chủ: vào vòng'; return true; }
    if (boss) C.hit = true;
    if (!ev('AUTO.on')) await G('auto on');
    AP.state = 'Bá Chủ ' + cur.boss + (boss ? ' máu ' + boss.hp + '%' : ' (chờ)'); return true;
  }
  const baseExt = AP.ext;
  AP.ext = async () => { try { if (await sb()) return true; } catch (e) { L('Bá Chủ lỗi ' + e.message); } return !!(baseExt && await baseExt()); };
})();
